"use strict";
const I18N_CARDS = {
"A1-01": {"n":"契約の呪い人形","f":"綿の代わりに契約書の切れ端を詰めて縫った人形。針が一本刺さるたび、ノクタールのどこかで署名した誰かが身をすくめる。","k":"呪い人形","h":"1nsb97b"},
"A1-02": {"n":"影泥棒","f":"灯の下は歩かない。財布より先に、持ち主の影を盗んでいくからだ。","k":"黒猫","h":"7ulnrj"},
"A1-04": {"n":"血の蝙蝠群","f":"ノクタール文書庫の天井にぶら下がって暮らす。インクが足りない時に書記たちが誰を呼ぶのか、誰も尋ねない。","k":"吸血蝙蝠","h":"137jo4e"},
"A1-05": {"n":"ノクタールの屍鬼","f":"借りを返しきれずに死んだ者は、ノクタールの裏路地で再び起き上がる。何を返すべきだったかは忘れても、飢えは忘れていない。","k":"グール","h":"194mxkc"},
"A1-06": {"n":"代価の影","f":"誰かがモルカスに代価として払った影。持ち主は真昼でも足元が心もとなく、影は夜ごと持ち主を探してノクタールをさまよう。","k":"奪われた影","h":"53n8r7"},
"A1-07": {"n":"影のドッペルゲンガー","f":"モルク峡谷の陰で出会った者の姿を借りてまとう。借りた代価はいつも元の持ち主が払う。","k":"ドッペルゲンガー","h":"12nepl7"},
"A1-08": {"n":"契約のサキュバス","f":"夢の中に現れて契約書を差し出す。目覚めると、掌に消えない天秤の跡が残っている。","k":"サキュバス","h":"1ni9v7e"},
"A1-09": {"n":"モルクの影蜘蛛","f":"峡谷の底に落ちたものは何であれ自分の糸にかかったものと見なす。影で編んだ糸ゆえ灯をかざせば見えず、灯が消えると再びぴんと張る。","k":"影蜘蛛","h":"1x8p1s3"},
"A1-11": {"n":"契約団の鼠兵","f":"深淵契約団のありふれた兵士。ありふれた者にも、モルカスは捧げた分の力を正確に返す。","k":"鼠","h":"1o2e59f"},
"A1-13": {"n":"ノクタールの首無し","f":"契約を破った者の名を帳簿から消す処刑人だった。己の首を代価に払ってからは、脇に抱えた首が帳簿を読み、体が奪うべきものを奪う。","k":"デュラハン","h":"6jt0t2"},
"A1-15": {"n":"血を啜る剣","f":"深淵の帳の縁で鍛えられた剣。持ち主が替わるたびに前の主の血の味を覚え、新しい主に同じ代価を求める。","k":"呪いの剣","h":"9ssxwn"},
"A1-17": {"n":"モルカスのバンシー","f":"顔なき影の王の言葉を伝える泣き声。彼女が戸口で泣けば、その家の契約は今日が満期だということだ。","k":"バンシー","h":"zgqp8n"},
"A1-18": {"n":"影の牙","f":"ノクタールの影絵劇場の裏手に棲む獣。舞台の悲鳴が芝居でないことが多いのはそのためだ。","k":"影の獣","h":"19wa18g"},
"A1-21": {"n":"血のラミア","f":"モルカスの祭壇の下でとぐろを巻き、捧げられた血を数える。足りなければ、捧げた者から残りを取り立てる。","k":"ラミア","h":"1azzlbn"},
"A1-23": {"n":"契約の死神","f":"満期を迎えた契約を刈り取って回る。その鎌が過ぎた跡には署名だけが残る。","k":"死神","h":"160ecoy"},
"A1-24": {"n":"月なき人狼","f":"満月の代わりに朔を選んでモルカスと契約した。月のない夜ならいつでも変われるが、その代価に二度と満月を見られない。","k":"人狼","h":"17l3qu9"},
"A1-25": {"n":"帳の三頭犬","f":"深淵の帳の入口を守る犬。入る者には吠えず、出てくる者が何を置いてきたか、三つの頭が順に嗅ぐ。","k":"地獄犬","h":"o3oenf"},
"A1-27": {"n":"ノクタール血の君主","f":"ノクタール文書庫の鍵を握る君主。都に流れる血はすべて彼の帳簿を通っていく。","k":"吸血鬼","h":"2n5b2z"},
"A1-28": {"n":"破れぬ契約書","f":"ノクタール文書庫から自ら歩き出た契約書。破ろうとした者は皆、いつの間にか署名欄に自分の名を書いている。","k":"契約書","h":"wz1ver"},
"A1-29": {"n":"深淵のオドゥクシニ","f":"帳の奥深くに長く留まって戻ってきたオドゥクシニ。歩くたびに道端の灯がひとつずつ消える。","k":"オドゥクシニ","h":"16lae85"},
"A1-30": {"n":"モルカスの剣","f":"沈黙の君主に名を捧げた剣士が握っていた剣。剣士はとうに消え、今は閉じた目が刻まれた剣だけがひとりで斬りに出る。","k":"呪いの剣","h":"1ai7p40"},
"A1-31": {"n":"血の公爵","f":"ノクタール貴族のうちで最も古い血。彼の宴に招かれた客は、杯の代わりに誓約書を受け取る。","k":"吸血鬼","h":"12c97um"},
"A1-32": {"n":"呪い軍団のリッチ","f":"己の命を一枚の契約書に預け、ノクタール文書庫の奥深くにしまい込んだ。ゆえに彼が率いる呪いの軍団には、行軍を止める理由がない。","k":"リッチ","h":"1mkx9gj"},
"A1-34": {"n":"代価の執行者","f":"モルカスは取引を必ず守る。相手が守らなければ、守らせるのが彼の仕事だ。","k":"顔なき者","h":"320qd3"},
"A1-35": {"n":"モルクのナイトメア","f":"峡谷の子らが眠る前に聞く話に出てくる黒い馬。大人がわざと話を短くするのは、最後まで聞いた子の夢に蹄の音が響くからだ。","k":"ナイトメア","h":"8xyj6s"},
"A1-41": {"n":"鎖に繋がれた亡霊","f":"返せなかった借りの代わりにノクタールに縛られた魂。剣は持てないが、彼を傷つければ契約が傷つけた側に代価を問う。","k":"亡霊","h":"91oo9b"},
"A1-42": {"n":"黒曜鎧の骸骨","f":"峡谷の黒い石で作った鎧だけが残り、中は空だ。鎧を着ていた者は、その鎧の代価に肉を払った。","k":"骸骨","h":"nc7ssg"},
"A1-43": {"n":"閉じた目の天秤","f":"モルカスの象徴たる天秤が体を得たもの。目を閉じているため誰が乗っても重さだけを量り、受けた打撃も片方の皿に積み上げていく。","k":"天秤","h":"1apizcj"},
"A2-01": {"n":"見習いの祈り燭","f":"暁城エラドの見習いが初めて捧げた祈りが、燭となって立ち上がった。炎はまだ指ほどだが、触れた傷の穢れを残らず焼く。","k":"燭の精","h":"1uzzhq3"},
"A2-03": {"n":"暁のヒバリ群","f":"陽より先に起き、エラドの城壁の上で鳴く。一羽でも寝坊すればその朝は少し遅れると、城壁の天族たちは信じている。","k":"ヒバリ","h":"1ssjrlm"},
"A2-04": {"n":"綿毛の子バト","f":"翼といっても綿毛が数枚だけの子バト。転ぶたびに、どこからか温かな光が支えてくれる。","k":"ハト","h":"10e5dwa"},
"A2-05": {"n":"紋章の鷲","f":"聖光騎士団の旗から飛び出したという鷲。旗のその場所は今も空いている。","k":"紋章獣","h":"1yy04nh"},
"A2-06": {"n":"さまよう光輪","f":"主なく高原の聖所を一つずつ巡る光輪。頭上に戴くに足る者を探すが、合う頭はまだない。","k":"光輪","h":"n6g7p3"},
"A2-07": {"n":"誓いのワルキューレ","f":"ソランテの前に誓いを一つ捧げ、槍を授かった。倒れた者を迎えに来るのではない。倒れる前に先に降りてくる。","k":"ワルキューレ","h":"ua8mv6"},
"A2-09": {"n":"暁の雄鶏衛兵","f":"聖光騎士団の最下列。だが、いつも最前列でもある。","k":"雄鶏","h":"s32no8"},
"A2-11": {"n":"幼きユニコーン","f":"角はまだ指の長さだ。それでもその角が指す所に、影は長く留まれない。","k":"ユニコーン","h":"1t791en"},
"A2-13": {"n":"聖光の彩窓騎士","f":"暁城の大聖堂の窓に描かれた騎士が、ガラスごと歩み出た。陽光がその身を通ると七色に分かれ、傷の穢れを洗う。","k":"彩窓騎士","h":"jokej2"},
"A2-15": {"n":"ソランテの誓約者","f":"ソランテに生涯を懸けた誓いを捧げた聖像。破れば容赦はないと知るゆえ、なお固く立つ。","k":"聖像","h":"q9pe73"},
"A2-16": {"n":"暁の巡回獅子","f":"闇が最も濃い夜明け前に高原を巡る。陽が昇ると、獅子のたてがみが通った道から明るくなる。","k":"暁獅子","h":"trt5eg"},
"A2-17": {"n":"問うスフィンクス","f":"エラドに入る者に問いを一つ投げる。答えが違うのは構わないが、偽りなら門は開かない。","k":"スフィンクス","h":"oswpor"},
"A2-20": {"n":"アルバトロス翼騎士","f":"翼を広げきれば城門ほど。その翼の下に仲間を皆入れてから、ようやく剣を抜く。","k":"アルバトロス","h":"i5vig"},
"A2-21": {"n":"誓いを守る白鳥","f":"生涯つがいを変えぬ鳥ゆえ、他者の誓いまで預かる。翼の下に預かった誓いが多く、いつも少し重たげだ。","k":"白鳥","h":"1hto6m9"},
"A2-22": {"n":"暁を告げる聖鐘","f":"暁城の朝の祈りが数百年積もり、一つの鐘に宿った。初鐘が鳴れば城壁の上に陽が昇るといわれ、陽もおおむねその言葉に従う。","k":"聖鐘の精","h":"1yi7viv"},
"A2-24": {"n":"光を返す鏡","f":"大聖堂の回廊に掛かり、暁の光を集めていた鏡。飛んできたものは、光であれ刃であれ来た道へ返す。","k":"鏡の精","h":"1jeoy6b"},
"A2-25": {"n":"エラドの聖火","f":"エラド大聖堂の祭壇で一度も消えたことのない火。倒れた者のそばに燃え移ると、傷に染みた穢れから焼く。","k":"聖火の精","h":"138yqs1"},
"A2-27": {"n":"暁のユニコーン","f":"昇る陽を背に負って駆けるユニコーン。その角は誓いを捨てた者の前でだけ光る。","k":"ユニコーン","h":"10gr5rp"},
"A2-28": {"n":"広場の聖者像","f":"暁城の広場の真ん中に立つ聖者像が目覚めた。台座を降りて戦いに出ても、広場のハトたちはその肩から降りない。","k":"聖像","h":"5z5heq"},
"A2-29": {"n":"暁城のワルキューレ長","f":"暁城のワルキューレの中で最も長く降り続けてきた者。城壁の石一つ一つに、彼女が守り抜いた朝が刻まれている。","k":"ワルキューレ","h":"1p3jqnd"},
"A2-30": {"n":"暁の三足烏","f":"ソランテの光を最も近くで浴びた三足烏。両翼は炎のように燃えるが、そばに立つ仲間は焼かない。","k":"三足烏","h":"10wrkwq"},
"A2-31": {"n":"四面のケルビム","f":"四つの顔が四方を見る。誓いを破った者がどちらへ逃げても、一つの顔と目が合う。","k":"ケルビム","h":"1eciud9"},
"A2-33": {"n":"大聖堂の彩窓守護者","f":"翼の盾を掲げる天使が描かれた大聖堂の大窓が、丸ごと目覚めた。ひびが入っても、その窓から差す光は漏れない。","k":"彩窓騎士","h":"15b60q0"},
"A2-34": {"n":"エラドの明星","f":"陽より先にエラドの上に昇る星が身を得た。それが留まった場所には、三日のあいだ影が落ちない。","k":"明星の精","h":"d52a3a"},
"A2-36": {"n":"暁の天使長","f":"ソランテの暁の光を真っ先に受ける天使長。彼が翼を広げると、高原全体に朝が来る。","k":"大天使","h":"5hizpw"},
"A2-41": {"n":"突撃ペガサス","f":"翼をたたんで高原を駆ける。飛べるのに、わざわざ駆けて体当たりする方を好む。","k":"ペガサス","h":"1b0it1v"},
"A2-42": {"n":"天罰の執行者","f":"誓いを破った者に下される光。ただ一度振り下ろすその刃は朔から得たもので、斬られた者の血は止まらない。","k":"審判霊","h":"g1yi3h"},
"A2-43": {"n":"炎翼の殉教者","f":"己の翼を燃やして光に変えたペリカン。その火は、そばに立つ仲間の傷に染みた穢れまで共に焼く。","k":"ペリカン","h":"2j8ins"},
"A3-01": {"n":"針の塔の見習い射手","f":"針の塔の最下層で、まず風の名前から覚える見習い射手。風を読めない矢は的の前で道に迷うと教わる。","k":"野ウサギ","h":"1xvd3gr"},
"A3-02": {"n":"幼いハーピー","f":"針の塔の軒に巣を作ったハーピーの雛。弓士会が捨てた矢羽根で巣を編むうち、羽根一枚で鎧の隙間を探す術を先に覚えた。","k":"ハーピー","h":"17kqwmi"},
"A3-04": {"n":"物見のフクロウ","f":"針の塔の物見台で夜通し地平線を見張る。弓より先に目が老いると射手たちは言うが、星に似たこのフクロウの目は老いない。","k":"星フクロウ","h":"m1tptx"},
"A3-05": {"n":"風のシルフ","f":"羽根のように軽く高原を渡り、敵の数を数える。見つかったと思う頃には、もう風に還っている。","k":"シルフ","h":"1l3tsg6"},
"A3-07": {"n":"突風インプ","f":"風より気の短い小さな精霊。射手が弦を引き切る前に矢をさらい、自分が先に当ててしまう。","k":"インプ","h":"umhiwa"},
"A3-09": {"n":"針の塔の鳥人弓兵","f":"ベルミルの針の外壁に住む鳥人。階段の代わりに翼で上り下りし、階ごとに的をひとつずつ立てた。","k":"鳥人族","h":"jn8ow5"},
"A3-10": {"n":"羽矢のハーピー","f":"自分の翼の羽根を抜いて矢として放つ。射ることは覚えたが惜しむことはまだで、通った跡に羽根が雪のように積もる。","k":"ハーピー","h":"xq8luc"},
"A3-11": {"n":"グリフィンの雛","f":"高原の聖所と針の塔を行き来して飛び方を学ぶ。便りを託しても、便りより先に自分が着いてしまう。","k":"グリフィン","h":"mndx07"},
"A3-13": {"n":"嵐のヒッポグリフ","f":"黒雲の下でしか翼を広げない。それが過ぎた跡を雨脚が追う。","k":"ヒッポグリフ","h":"1mip9ue"},
"A3-15": {"n":"テンの狙撃手","f":"風ごとに名があると知るゆえ、一矢で足りる。他の射手が風を責めるとき、彼は風を呼ぶ。","k":"テン","h":"1qxjgq2"},
"A3-16": {"n":"鎧隙のハヤブサ","f":"鎧の継ぎ目だけを見る。爪は鉄を貫かず、鉄が譲った隙間から入る。","k":"ハヤブサ","h":"1fy3gu1"},
"A3-18": {"n":"双子座の弓手","f":"夜空の双子星が弓を二張り携えて降りてきた。一方の星が射た矢の道を、もう一方の矢がそのまま辿る。","k":"星座","h":"1jtkjly"},
"A3-19": {"n":"嵐の塔の鳥人弓手","f":"嵐の塔弓士会の正式な射手となった初の鳥人。傲慢だと言われれば、エルフに学んだと答える。","k":"鳥人族","h":"mbgpna"},
"A3-20": {"n":"ベルミルの開いた書","f":"ベルミルの象徴たる開いた書が身体を得た。風がめくる頁ごとに星の文字が浮かび、鎧を越えてその内を読み、貫く。","k":"魔導書","h":"1bzcenm"},
"A3-22": {"n":"風乗りグリフィン","f":"空気の重さを羽根の先で量る。それが翼をたたむと風も止み、その隙に急降下する。","k":"グリフィン","h":"mol3py"},
"A3-23": {"n":"ベルミルの星狐","f":"イヴェルの書庫を探す射手たちについて、星座高原を生涯歩いた。書庫はまだ見つからないが、尾の星明かりで高原のすべての道に印をつけた。","k":"星狐","h":"1kgaald"},
"A3-24": {"n":"雷矢の天狗","f":"雷を孕む雲の下でしか弓を取らない。羽団扇をひと扇ぎすれば、矢じりに雷が降りる。","k":"天狗","h":"jhyxvu"},
"A3-26": {"n":"嵐狩りヒッポグリフ","f":"嵐を追って高原をさまよう狩人。嵐が連れてきた獣も、嵐の陰に潜む敵も、その爪の取り分だ。","k":"ヒッポグリフ","h":"1bpqw8k"},
"A3-28": {"n":"流れ星インプ","f":"流れ星の尾にしがみついて落ちてきたちび。空への帰り道を知らず、針の塔の頂で星が通るたびに手を振る。","k":"インプ","h":"15w6b12"},
"A3-29": {"n":"弓引く射手座","f":"嵐の塔の射手が初めて弓を握るとき見上げる星座。射手座が弦を放つ夜、弓士会はその年最初の的を決める。","k":"星座","h":"18545zx"},
"A3-30": {"n":"嵐のハヤブサ","f":"嵐を連れて飛ぶ鳥。弓士会が手なずけたという話より、鳥が弓士会を手なずけたという噂のほうがもっともらしい。","k":"ハヤブサ","h":"1b5wc0c"},
"A3-31": {"n":"欠片諸島の名弓","f":"アウラゴンの欠片諸島で独り百年射続けた。シレルが散らす風の中でも外さなくなった日、ようやく戻った。","k":"岩山羊","h":"1k7oisl"},
"A3-32": {"n":"つむじ風の天狗","f":"つむじ風を三つ同時に起こし、一矢で貫く。弓士会はそれを技と呼び、天狗は癖と呼ぶ。","k":"天狗","h":"i9pkay"},
"A3-33": {"n":"星を狙う者","f":"空から落ちる代わりに、別の星を狙って昇る流れ星。それがかすめた星は、その夜一度瞬く。","k":"流れ星","h":"gu6ts3"},
"A3-34": {"n":"ハーピーの女王","f":"頭上には常に雷雲が冠のように巡る。針の塔の軒のハーピーは皆、彼女の巣で生まれた。","k":"ハーピー","h":"496qyz"},
"A3-35": {"n":"天裂くロック鳥","f":"翼をひと広げすれば雲が裂ける。それが過ぎた空には、一筋の裂け目が長く残る。","k":"ロック鳥","h":"1ble6xr"},
"A3-36": {"n":"嵐の塔の塔主","f":"嵐の塔弓士会を率いる塔主。イサクが建てた塔の鍵と、その塔の最初の弓が、今は彼の手にある。","k":"雲の巨人","h":"1kavdcv"},
"A3-41": {"n":"静寂の雲鯨","f":"風の者たちの中で静けさを好む変わり者の鯨。その雲の身に入った烈風は息をひそめる。","k":"雲鯨","h":"qlufbp"},
"A3-42": {"n":"嵐の瞳","f":"ベルミルのローブに嵌まった千の目のひとつが外れ落ちた。嵐の只中に浮かび、外が荒れるほど静かに睨み、不用意に近づく者は風が斬る。","k":"千眼","h":"fhpnx9"},
"B1-02": {"n":"火薬運び","f":"自分より大きな火薬袋を背負い、ノコギリ峠を上り下りする。転んではならないことだけは誰よりも知っている。","k":"灰ラバ","h":"lejhgc"},
"B1-03": {"n":"燃えゆく導火線","f":"フォルタンの火薬庫で誰かが火をつけたまま忘れた導火線が、自ら這い出してきた。触れるものすべてに火を移し、己の先に何が繋がれているかは問わない。","k":"導火線の精","h":"1xe3eay"},
"B1-05": {"n":"炎のインプ","f":"火冠山脈の火口から跳ねた火の粉が手足を得た。フォルタンのゴブリンは可愛がるが、火薬庫の前でだけは箒を構える。","k":"炎のインプ","h":"c5m0bb"},
"B1-08": {"n":"煙幕の精","f":"砲台が一斉に鳴った日、最後まで散らなかった硝煙の塊が体を得た。敵の咳を追って、ゆっくりと近づく。","k":"煙の精","h":"olgvio"},
"B1-10": {"n":"フォルタン火犬","f":"ノコギリ峠の砦の門前に棲む火犬。昔は太陽に噛みつこうとしたというが、今は門を通る足首に目を落とした。","k":"火犬","h":"j5d4nr"},
"B1-12": {"n":"火鼠の群れ","f":"火冠山脈の冷めない岩の隙間に棲む火鼠の群れ。毛は火に入っても燃えず、フォルタンはその毛で火薬庫の手袋を編む。","k":"火鼠","h":"gaq8xo"},
"B1-13": {"n":"残り火蝙蝠","f":"火口の天井にぶら下がり、残り火を食べて育った蝙蝠たち。一斉に飛び立てば、翼の火の粉が雨のように降る。","k":"炎の蝙蝠","h":"b17w6z"},
"B1-14": {"n":"錆鉄の火猿","f":"錆鉄丘陵の岩場で焼け石を投げて遊ぶ猿。フォルタンの狙撃兵が彼に隠れ方を習ったとは、誰も認めない。","k":"火猿","h":"1tm9oyn"},
"B1-16": {"n":"灰狸の爆破工","f":"フォルタンで爆薬を扱う手が最も速い灰狸。計算は苦手でも、導火線の長さだけは間違えたことがない。","k":"灰狸","h":"iemlrc"},
"B1-17": {"n":"砲台亀","f":"甲羅の真ん中に小さな火口を背負った溶岩亀。フォルタンの砲手は、その穴が大砲より遠くまで撃つと認めたがらない。","k":"溶岩亀","h":"r56uyd"},
"B1-18": {"n":"火薬庫の火蟻","f":"フォルタンの火薬庫の下に巣を掘った火蟻の群れ。ゴブリンは追い出すのを諦めて庫番を任せたが、蟻は元から自分の家だと思っている。","k":"火蟻","h":"col1go"},
"B1-21": {"n":"火牙の猪","f":"牙の先がいつも赤く焼けている火冠山脈の猪。ノコギリ峠の斜面を駆け出せば止まれず、止まる場所がすなわちぶつかる場所だ。","k":"火猪","h":"jrvkqi"},
"B1-22": {"n":"火を噴くキマイラ","f":"ドルマクの心火の近くで、獣三匹がひとつの体に溶け合った。三つの頭が先に火を噴こうと争うので、森はいつも三度燃える。","k":"キマイラ","h":"1mkyk4d"},
"B1-24": {"n":"ウルヴァリン迫撃手","f":"砲弾を高く放り、城壁の向こうへ落とす。撃たれる側は、音より先に影を見る。","k":"ウルヴァリン","h":"1l4nnfk"},
"B1-25": {"n":"攻城ガマ","f":"喉袋に溶岩を含み、城壁越しに吐くガマ。一度吐くのに半日膨らむので、その間フォルタンは歌を聞かせてやる。","k":"炎のガマ","h":"14dm2fe"},
"B1-26": {"n":"火冠の炎巨人","f":"ドルマクの心火が溢れて火冠山脈の斜面を流れ、人の形に固まった。巨人と呼ばれるが、ドルマクの指一本にも及ばぬことを本人が一番知っている。","k":"炎巨人","h":"1ri92ii"},
"B1-27": {"n":"爆炎のイフリート","f":"火冠山脈の煙柱から生まれた炎の精霊。フォルタンの技師長が火薬の配合を尋ねに来ると、答えの代わりに工房の壁へ煤の跡をひとつ増やす。","k":"イフリート","h":"rm9i1r"},
"B1-30": {"n":"溶岩穴ワーム","f":"火冠山脈の下を掘り進み、固まった溶岩を食べる虫。それが通った地には、翌年も草が生えない。","k":"溶岩ワーム","h":"m2xrz4"},
"B1-31": {"n":"火冠の火蛇","f":"火冠山脈の溶岩の川を遡って泳ぐ蛇。噛まれた跡は、蛇が去った後も長く燃える。","k":"火蛇","h":"1xiy6e"},
"B1-32": {"n":"タラクスの瀝青魔","f":"地下の血脈を伝って昇ったタラクスの黒い血が、ドルマクの火に焼かれて立ち上がった。歩むたびに粘つく足跡が残り、フォルタンはそれを掬って火薬に混ぜる。","k":"瀝青の怪物","h":"wmjsle"},
"B1-33": {"n":"ドルマクの火口","f":"ドルマクの心火が息をしていた穴のひとつが、山を離れて歩き出した。吸うときは静かで、吐くときは遠い空から石が降る。","k":"火口","h":"zaobzw"},
"B1-34": {"n":"火冠ベヒモス","f":"火冠山脈の尾根だと思われていたものが、ある日起き上がって歩いた。それが通った後、道の名がよく変わった。","k":"ベヒモス","h":"ga1gow"},
"B1-36": {"n":"炸裂の獅子王","f":"たてがみの一本一本が導火線だという獅子王。フォルタンでは、最も大きく爆ぜさせた者が治める。","k":"火薬獅子","h":"1ikiaf6"},
"B1-41": {"n":"灰殻カタツムリ","f":"冷えた灰で殻を覆い、その中に火を抱くカタツムリ。一日に手のひらほどしか進まないが、殻に触れた手はその夜ずっと疼く。","k":"溶岩カタツムリ","h":"8jm32g"},
"B1-42": {"n":"沸く溶岩スライム","f":"火口の底から流れ出て、冷めも固まりもしない溶岩の塊。砲弾が落ちてもたぷんと呑むだけで、斬りつけた剣は溶けて戻る。","k":"溶岩スライム","h":"12t2vj"},
"B1-43": {"n":"フォルタン窯の精","f":"フォルタンで最も長く消えなかった窯が立ち上がり、ノコギリ峠を塞いだ。森から来た者たちは、その焚き口の前で煤けて帰った。","k":"窯の精","h":"1l56ibr"},
"B2-01": {"n":"リベット職人","f":"ドゥルクハイムの工房で嘴でリベットを打つキツツキ。一日に打ったリベットの列の長さが、その日の賃金だ。","k":"鉄嘴キツツキ","h":"a8x18"},
"B2-02": {"n":"歯車ゼンマイネズミ","f":"ドゥルクハイムの見習いが最初に作るゼンマイネズミ。指一本は噛まれてこそ職人になれる、という言葉はこのネズミから生まれた。","k":"ゼンマイネズミ","h":"1dzsb1e"},
"B2-05": {"n":"ドゥルクハイム見習い","f":"地下都市に来たばかりの見習い。まだ陽の匂いが残っていて、先輩たちに嗅がれてからかわれる。","k":"鉄甲センザンコウ","h":"n9fm65"},
"B2-06": {"n":"鋼の門番鎧","f":"工房の扉の前の空の鎧が、鉄の心臓が初めて脈打った日に共に目覚めた。入ろうとする者に問うことは今も一つ。「誰の髭だ」。","k":"リビングアーマー","h":"1nrrx99"},
"B2-07": {"n":"歩くリベット盾","f":"主を失ったリベット盾が独りで立ち上がり、前を塞ぐ。凹んだ所にはリベットがひとりでに生え、防いだらそのまま打ち下ろす。","k":"目覚めた盾","h":"mji2fl"},
"B2-09": {"n":"蒸気ゴーレム","f":"ボイラー一つで動くゴーレム。力は強いが、蒸気が抜けるとため息のようにその場で止まる。","k":"ゴーレム","h":"li5mlu"},
"B2-12": {"n":"鍛冶見習い","f":"金床の前で槌を学ぶ見習い職人。掌のたこが師匠のものに似てきた。","k":"鉄の猿","h":"1qbhxal"},
"B2-15": {"n":"鋼の鍛冶師","f":"ソルグリムの腱から掘った鉄を打つ。彼の鍛えた鋼は冷めても唸り続ける。","k":"単眼巨人","h":"1lassz"},
"B2-16": {"n":"装甲ゼンマイ蜘蛛","f":"重ね装甲をまとう八本脚のゼンマイ機械。坑道の天井にぶら下がり、命じられた仕事を終えるまで落ちない。","k":"ゼンマイ蜘蛛","h":"12wgfn1"},
"B2-17": {"n":"鉄角ヤギ","f":"鉄骨山脈の露出した鉱脈を舐めるうち、角が鉄に育ったヤギ。彼が踏ん張る岩こそが城壁の果てだ。","k":"鉄角ヤギ","h":"1me2fdw"},
"B2-18": {"n":"蒸気鼻息の牡牛","f":"ドゥルクハイムの職人が青銅で鋳て腹にボイラーを据えた牡牛。鼻息一つで地下都市の灯が揺れる。","k":"青銅の牡牛","h":"1f6zt93"},
"B2-19": {"n":"歩く金床","f":"ドゥルクハイムで最も長く打たれた金床が、鉄の心臓が脈打った日に脚を得た。打たれた分を返す術は、幾代もの職人の槌の下で覚えた。","k":"目覚めた金床","h":"1bnzdti"},
"B2-22": {"n":"鉄喰いプルガサリ","f":"初めは針ほどだった獣が、ドゥルクハイムの釘と錠を喰ってここまで育った。倒すには城一つを崩すほどの手間がかかる。","k":"プルガサリ","h":"1y7ixjg"},
"B2-24": {"n":"鉄骨ガーゴイル","f":"鉄骨山脈の崖で錆びた鉱脈を齧って生きるガーゴイル。坑道の入口では石像と見紛うが、骨組みを風が抜けるとき低い唸りが聞こえる。","k":"鋼のガーゴイル","h":"a8bmfp"},
"B2-25": {"n":"工房守護ゴーレム","f":"ドゥルクハイム工房の最も深い部屋を守るゴーレム。その部屋に何があるかは、問わないのが礼儀だ。","k":"ゴーレム","h":"chjv5h"},
"B2-26": {"n":"ソルグリムの鉄犀","f":"ソルグリムの腱が露わな鉱脈で、赤黒い鉄を食んで育ったサイ。彼が歩くたびに眠る腕が蠢くという。","k":"鉄甲サイ","h":"vj3ck4"},
"B2-27": {"n":"ドゥルクハイム近衛長","f":"ドゥルクハイムの城門の近衛を担う将。そのたてがみには、これまで防いだ刃の欠片が編み込まれている。","k":"ヘテ","h":"74oluy"},
"B2-28": {"n":"流れる水銀","f":"ソルグリムの腱の間を流れていた銀の血が坑道に漏れ出た。槌で打てば散り、足元でまた一つに集まる。","k":"水銀スライム","h":"m2ys8m"},
"B2-30": {"n":"鉄骨山脈ワイバーン","f":"鉄骨山脈の露出した鉱脈の上を巡る鉄鱗のワイバーン。その下の深みで飛ばぬ竜フェロスが見ていると知るのか、めったに地に降りない。","k":"鉄のワイバーン","h":"3rn68i"},
"B2-32": {"n":"歩く鉄の城塞","f":"ドゥルクハイムの職人が城塞に脚を付けた。まだ倒れたことはないが、城門を通すため都市の半分を掘り直した。","k":"攻城兵器","h":"jpfri2"},
"B2-33": {"n":"オルドゥンの骨騎士","f":"オルドゥンの背骨から掘った灰色のアダマントの鎧が、着る者もなく立ち上がった。巨人の骨の騎士は膝を折ることを知らない。","k":"リビングアーマー","h":"7tmew5"},
"B2-34": {"n":"大蒸気巨像","f":"溶鉱炉一つを心臓とする蒸気の巨像。息を吐けば坑道全体が白い湯気に沈む。","k":"巨像","h":"1d2mteq"},
"B2-35": {"n":"ドゥルクハイム大匠","f":"ドゥルクハイムの工房を率いる大匠。鉄の心臓を呑んだ者以来、最も多くのゴーレムが彼の鼻先を経た。","k":"鉄の象","h":"nksr02"},
"B2-36": {"n":"青銅の守護巨人","f":"ドゥルクハイムが青銅を流して建てた守護巨人。足首の釘一本を抜けば倒れるというが、その釘まで辿り着いた者はまだいない。","k":"青銅の巨人","h":"xsdsp6"},
"B2-41": {"n":"暴走ゼンマイ人形","f":"ゼンマイを巻きすぎたまま放たれた人形。止まり方を知らないので、ぶつかる他にすることがない。","k":"オートマトン","h":"1d5m0di"},
"B2-42": {"n":"過熱プレス機","f":"鉄塊を押し延ばしていたプレス機が熱に狂った。今は前にあるものを何でも平たくする。","k":"オートマトン","h":"6qybq5"},
"B2-43": {"n":"自爆オートマトン","f":"最後の命令一つだけを刻まれたオートマトン。その命令が何か皆知っているから、誰も傍に立たない。","k":"オートマトン","h":"1kn08gn"},
"B3-02": {"n":"蓄電見習い","f":"蓄電瓶を運びながら雷の扱いを学ぶ。いつも空へ逆立つ毛が見習いの印だ。","k":"電気羊","h":"cfgg7i"},
"B3-03": {"n":"雷ホタルの群れ","f":"ケラウンの神経が地上に弾けた場所に群がるホタル。ヴォルタリウムの子らは瓶に詰めて灯りにし、髪を逆立てる。","k":"ホタル","h":"1fvc1s1"},
"B3-04": {"n":"静電気の妖精","f":"毛皮と琥珀の間に生まれる爪ほどの妖精。ドアノブに潜み、手が触れた瞬間パチッと笑う。","k":"スパーク妖精","h":"5wjq5j"},
"B3-05": {"n":"ヴォルタリウム学徒","f":"雷電学術院に入ったばかりの学徒。最初の試験は、雷に打たれてもノートを落とさないことだった。","k":"ミーアキャット","h":"196goe9"},
"B3-06": {"n":"雷鳥のひな","f":"雷鳴高原の黒雲の中で孵ったばかりの雷鳥。羽ばたきは拙くとも、羽先からはもう火花が散る。","k":"雷鳥","h":"1cj76jq"},
"B3-09": {"n":"電流ムササビ","f":"避雷塔の間を滑空するムササビ。止まるたびに銅線が切れ、ヴォルタリウムの修理工に最も嫌われる。","k":"ムササビ","h":"1a7mqhm"},
"B3-10": {"n":"避雷針ガラス","f":"ヴォルタリウムの避雷塔の頂に巣くうカラス。嵐の日も飛び去らず、雷が巣を訪れるのを待つ。","k":"嵐ガラス","h":"1jqu96e"},
"B3-12": {"n":"放電妖精","f":"溜めた雷が一度に弾ける瞬間にだけ姿を現す妖精。ヴォルタリウムの実験室の壁が毎回塗り直される理由だ。","k":"スパーク妖精","h":"11tls30"},
"B3-13": {"n":"ヴォルタリウムの人造人","f":"研究生が瓶の中で雷により目覚めさせた小人。夜通し雷の流れを記すが、記録はいつも「追加実験が必要」で終わる。","k":"ホムンクルス","h":"8wy0d"},
"B3-14": {"n":"霹靂ウナギ","f":"錆水川の底で霹靂を抱いて生きるウナギ。フォルタンのゴブリンは火薬の匂いがしないものは信用できぬと、川に足を入れない。","k":"雷ウナギ","h":"42bgpz"},
"B3-15": {"n":"鎖雷の精霊","f":"一つの輪に触れると次の輪へ跳ねる雷の精霊。捕らえようとした学者は、三つ目の輪あたりで手を放した。","k":"雷の精霊","h":"o20t9"},
"B3-16": {"n":"充電グモ","f":"避雷塔の鉄骨に銅色に光る糸を張るクモ。獲物はもがくほど巣に雷を満たしてくれる。","k":"電気グモ","h":"f178vb"},
"B3-18": {"n":"メガネザル技師","f":"歯車より回路を信じる技師。ドゥルクハイムの職人と夜通し論争し、朝には共に槌を握る。","k":"メガネザル","h":"1b8sc81"},
"B3-20": {"n":"雷針サソリ","f":"尾の先に雷を溜めて撃つ雷鳴高原のサソリ。その尾を模した設計図の幾枚かは、学術院でも禁書だ。","k":"雷サソリ","h":"1tyo194"},
"B3-22": {"n":"電撃守護機","f":"ヴォルタリウムの城門に据えた雷の守護機。近づく者の鉄から先に見抜く。","k":"雷電機関","h":"ujrdl2"},
"B3-23": {"n":"瓶詰め教授の脳","f":"学術院一の長講義の教授が、体を捨てて瓶に入った。講義はさらに長くなり、居眠りする学生は今も雷で目覚める。","k":"瓶詰めの脳","h":"1x6suyv"},
"B3-24": {"n":"閃光ガ","f":"雷が鳴る時だけ羽を広げるガ。一度の羽ばたきで眩い光が弾け、間近で覗いた学者は数日目が見えなかった。","k":"雷ガ","h":"5hs1n6"},
"B3-25": {"n":"ケラウンの雷精","f":"ケラウンが夢見る夜、神経を伝い地上へ飛び出た雷が体を得た。その通り道の針はすべて狂い跳ねる。","k":"雷の精霊","h":"rcaa0j"},
"B3-26": {"n":"雷電博士","f":"雷に打たれて生き延びた回数で博士になったオオサンショウウオ。体に残る紋様が学位証だ。","k":"オオサンショウウオ","h":"15lnftb"},
"B3-27": {"n":"大型蓄電器","f":"ヴォルタリウムの地下に置かれた巨大な蓄電器。中の雷が一度に解き放たれる日を、皆が恐れている。","k":"蓄電器","h":"1wwgtvc"},
"B3-29": {"n":"ケラウンの雷雲","f":"雷鳴高原の上に晴れず留まる黒雲。その下で放つ魔法に、雲が雷をひと握りずつ添える。","k":"雷雲","h":"oynd1"},
"B3-31": {"n":"電撃要塞","f":"城壁の代わりに雷を巡らせた要塞。ヴォルタリウムに近づく者は、柵を越える前に髪が逆立つ。","k":"雷電塔","h":"bgvujq"},
"B3-32": {"n":"雷嵐の巨人","f":"アウラゴンの散った息が雷鳴高原の雷と出会い、巨人の姿に固まった。一歩ごとに空が応えるように轟く。","k":"嵐の巨人","h":"1mzwmqj"},
"B3-33": {"n":"ヴォルタリウム学長","f":"ヴォルタリウム雷電学術院を率いる学長。アストラクの雷を瓶に詰める夢を最初に見た者だ。","k":"白鶴","h":"fm7jgd"},
"B3-34": {"n":"爆雷機関","f":"雷を溜めて一度に炸裂させる機関。ノームはその息づく音だけで避け時を知る。","k":"雷電機関","h":"1qk7w18"},
"B3-36": {"n":"霹靂の雷獣","f":"霹靂と共に空から落ちてくるという獣。それがうずくまる場所では、ヴォルタリウムの装置がひとりでに強く回る。","k":"雷獣","h":"dbf732"},
"B3-41": {"n":"絶縁防護機","f":"雷がそれるようゴムと磁器で包んだ防護機。ヴォルタリウムでは最もつまらない発明とされる。","k":"雷電機関","h":"1lxns9r"},
"B3-42": {"n":"棘触手の雲クラゲ","f":"嵐雲の間を漂い、触手で霹靂を地へ流すクラゲ。触れた者はその霹靂の通り道になる。","k":"雲クラゲ","h":"3l4ck4"},
"C2-1": {"n":"見習いの短弓","f":"針の塔の見習いに最初に渡される短い弓。拳の代わりに風で打つ。","h":"1kol828"},
"C3-1": {"n":"嵐の弓","f":"弦に小さな嵐が巻きついた弓。引かずとも雷の矢が弾ける。","h":"17pu9rz"},
"C4-1": {"n":"星読みの宝珠","f":"イサクが星の文字を読むのに使った宝珠。一度弾けた雷が次の的を自ら探す。","h":"nacnko"},
"CS-A1": {"n":"沈黙の憑依","t":"相手の先頭の魔法1枚を[無効]にする。相手ユニットのうち残り体力が最も高いユニット1体に[憑依] — 残り体力が、戦場でレベルが最も低い他のユニットの残り体力になる(より低い場合のみ)。","f":"呪文を唱える口が止まり、最も屈強な者の体に最もか弱い者の魂が宿る。モルカスの朔には、どちらも同じ値だ。","b":"{敵魔法1枚} [無効]|{敵♥最高1体} ♥ = 戦場最低レベルの♥","h":"1icd01x"},
"CS-A2": {"n":"浄化の光","t":"相手の先頭の魔法1枚を[無効]にする。味方の先頭ユニットの攻撃+2、[障壁]。","f":"ソランテの光の下では、隠したものは残らない。暴かれた罠は消え、先に立つ騎士の槍先に光が宿る。","b":"{敵魔法1枚} [無効]|{味方前1体} ⚔+2 [障壁]","h":"ue6ect"},
"CS-A3": {"n":"呪文断ち","t":"相手先頭の魔法1枚を[無効]にする。","f":"嵐の塔の見習いは、呪文をかけるより断つ術を先に学ぶ。他者の呪文を断てぬ者は塔に登れない。","b":"{敵魔法1枚} [無効]","h":"bl8lxr"},
"CS-B1": {"n":"罠焼き","t":"敵の先頭の魔法1枚を[無効]にする。敵の先頭ユニット2体の体力−1。","f":"ゴブリンは罠を解除しない。火を投げ込み、爆ぜるのを見物する。罠の前に立っていた者も共に見物することになる。","b":"{敵の魔法1} [無効]|{敵前2体} ♥−1","h":"1pjqta4"},
"CS-B2": {"n":"封印の楔","t":"相手の先頭の魔法1枚を[無効]にする。","f":"呪文に幾度か焼かれたドワーフは鉄の楔を作った。ドゥルクハイムの楔を打たれた呪文は二度と開かない。","b":"{敵魔法1} [無効]","h":"1dyvs95"},
"CS-B3": {"n":"短絡","t":"相手の先頭の魔法1枚を[無効]にする。","f":"どんな呪文も結局は流れだ。ヴォルタリウムのノームは流れの通り道に銅線を一本渡すだけだ。","b":"{敵魔法1} [無効]","h":"1z0htia"},
"CS-G1": {"n":"罠踏み","t":"相手の先頭の魔法1枚を[無効]にする。","f":"ガルウンのオークは罠を避ける術を知らない。代わりに、罠が起きる前に踏み砕く術は知っている。","b":"{敵魔法1枚} [無効]","h":"1dh2bw4"},
"CS-G2": {"n":"苔覆い","t":"敵の先頭の魔法1枚を[無効]にする。無効にしたら、味方先頭ユニット2体の攻撃+1、体力+2。","f":"苔は何でも覆う。覆われた呪文は息が詰まって消え、その上を踏んでいくトロールの傷は苔の下でまた育つ。","b":"{敵魔法1} [無効]|無効にしたら {味方前2体} ⚔+1 ♥+2","h":"v5eydm"},
"CS-G3": {"n":"禊の歌","t":"敵の先頭の魔法1枚を[無効]にする。無効にしたなら、敵ユニット全体の[障壁]・[棘]・[呪い免疫]・[守護]が消え、攻撃−1。","f":"泉の巫女団の歌は掛けられたものを洗い流す。広げようとした呪文が水に溶ければ、それを信じた者たちの祝福と闘志も共に流れ落ちる。","b":"{敵魔法1枚} [無効]|無効なら{敵全体} 解除 ⚔−1","h":"18wyiq"},
"EP-A1-1": {"n":"深淵の刃舞姫","f":"ノクタールの影絵劇場で踊るカマキリ。踊りが終わると、観客がひとり減っている。","k":"カマキリ","h":"1xdehmc"},
"EP-A1-2": {"n":"ノクタール処刑長","f":"契約を破った者を刈りに行く処刑人たちの頭。一振りで、並んだ者たちが次々と倒れる。","k":"ウェンディゴ","h":"12nc1r8"},
"EP-A1-3": {"n":"帳の処刑者","f":"深淵の帳から歩み出たもの。何を置いてきたのか尋ねた者が次の番になる。","k":"亡霊","h":"39vsj1"},
"EP-A2-1": {"n":"暁城門番ラマッス","f":"エラドの城門の柱に刻まれていた翼ある牡牛。門が初めて開いた日に目覚め、以来一度も門前を空けたことがない。","k":"ラマッス","h":"qwgjhu"},
"EP-A2-2": {"n":"黄昏障壁の守将","f":"空白の地に面した黄昏の障壁を守る白狼。障壁の向こうから何が来ようと、真っ先に受けるのが彼の務めだ。","k":"白狼","h":"dvouyt"},
"EP-A2-3": {"n":"黄昏の大天使","f":"ソランテの六枚の翼の一枚を授かったという大天使。その翼の下に立つ者は、日が沈むまで倒れない。","k":"大天使","h":"wliacy"},
"EP-A3-1": {"n":"針の塔のシルフ射手","f":"針の塔弓士会で弓を学んだ風の精霊。己が風ゆえ、矢の代わりに星の文字だけを乗せても的まで届く。","k":"シルフ","h":"1f05mk5"},
"EP-A3-2": {"n":"雷雲の鯨","f":"身にまとう雷雲が最初の刃を散らす。それが頭上を過ぎる間は、味方の呼ぶ雷も太く落ちる。","k":"雲鯨","h":"1lwiu46"},
"EP-A3-3": {"n":"天の揺籃の番人","f":"針の塔の頂の関門の先、天の揺籃を守る大きな星フクロウ。風の竜シレルもその目と合えば悪戯をやめる。","k":"星フクロウ","h":"fgjv9z"},
"EP-B1-1": {"n":"フォルタン擲弾長","f":"擲弾兵百人分をひとりで投げる。火薬の匂いがしない日はない。","k":"火猿","h":"18cko5c"},
"EP-B1-2": {"n":"火冠の不死鳥","f":"火冠山脈の頂で焼け死んでは蘇るを繰り返す鳥。山麓の砲台の火縄を狙って急降下し、煙が晴れる頃にはもう灰となって別の巣にいる。","k":"不死鳥","h":"au8s4a"},
"EP-B1-3": {"n":"竜狙いの巨砲","f":"フォルタンがイグナルを撃つと鋳造した巨砲が、ある日自ら砲口を上げた。竜に撃ったことはまだないが、火冠山脈を向くと砲身が熱を帯びる。","k":"目覚めた大砲","h":"1mnynm5"},
"EP-B2-1": {"n":"棘鉄ハリネズミ","f":"工房に捨てられたリベットを拾って食べるうち、棘が鉄になったハリネズミ。前を塞いで丸まることしか知らないが、それが厄介だ。","k":"鉄のハリネズミ","h":"1r1cpk3"},
"EP-B2-2": {"n":"鋼の粉砕ゴーレム","f":"ドゥルクハイムの鉱山で岩を砕いていたゴーレムを戦に出した。鎧も岩のように砕く。","k":"ゴーレム","h":"9vs2g7"},
"EP-B2-3": {"n":"ドゥルクハイム城門巨像","f":"地下都市の城門そのもの。門が歩き出せば都市が空くのでは、という問いに工房長は「門は戻る」とだけ答えた。","k":"巨像","h":"1365u2l"},
"EP-B3-1": {"n":"ヴォルタリウム放電体","f":"ヴォルタリウムが雷で目覚めさせた実験体。体に残る電気を少しずつ流して飛来物を落とし、余れば味方の魔法に乗せる。","k":"実験体","h":"gr344c"},
"EP-B3-2": {"n":"連鎖雷蛇","f":"一つの体を噛むと次の体へ跳ぶ雷蛇。学者は生涯その訳を追ったが、蛇はまだ一度も止まったことがない。","k":"雷蛇","h":"1azfltu"},
"EP-B3-3": {"n":"ケラウンの避雷塔","f":"雷鳴高原の下に眠る巨人の神経の上に建てた塔。歩けるようにしたのはノームの意地だ。","k":"雷電塔","h":"10hjivg"},
"EP-G1-1": {"n":"黒曜サイクロプス闘士","f":"単眼と黒曜石の籠手ひとつで、ガルウン決闘場で三十勝した。ゴルヴァスが片目を開けて見た戦いもその一つだ。","k":"サイクロプス","h":"ynll2o"},
"EP-G1-2": {"n":"ケサイの騎手","f":"吠える草原のケサイが背を許した唯一のオーク。ひとつ突き倒しても止まらず、次の隊列へ突き進む。","k":"ケサイ","h":"8h8gys"},
"EP-G1-3": {"n":"王座峰の決闘王","f":"ゴルヴァスの眠る王座峰まで登り、決闘を挑んだシルバーバック。竜は目覚めなかったが、道中で出会った者は皆倒れた。","k":"シルバーバック","h":"1ynu0gm"},
"EP-G2-1": {"n":"アザミの蔓鬼","f":"錆の沼のほとりで、アザミと蔓が絡み合って立ち上がったもの。錆水を飲み、棘が鉄のように固まった。","k":"蔓の怪物","h":"1gb8elk"},
"EP-G2-2": {"n":"弓のドライアド","f":"巨樹の都の最も高い枝に宿るドライアド。矢が落ちる頃には、射た場所は葉に覆われている。","k":"ドライアド","h":"1iw8zci"},
"EP-G2-3": {"n":"ヴェルダンの古木巨人","f":"太古林山脈から下りてきた古木。ヴェルダンの角から落ちた枝が育ったという話がある。","k":"トレント","h":"117rdyo"},
"EP-G3-1": {"n":"真珠色のクラゲ","f":"巫女団の真珠を呑んで光を得たクラゲ。身を一度すぼめれば波が立ち、刃先を受け流す。","k":"クラゲ","h":"1pdf2h"},
"EP-G3-2": {"n":"深海ナーガ銛騎士","f":"タラクス海溝でウルボアの鱗を貫いたという銛を持つナーガ。銛は投げれば潮に乗って戻ってくる。","k":"ナーガ","h":"r2rxxj"},
"EP-G3-3": {"n":"マレンシア大巫女","f":"水の竜マレンシアとの盟約を結び直す儀式を率いる巫女。彼女を斬った剣は、水を斬ったように手が濡れる。","k":"オケアニス","h":"zo79j4"},
"G1-01": {"n":"決闘場の仔バイソン","f":"ガルウン決闘場の柵の外で、兄たちの戦いを見て育った。今日、初めて柵の中へ入る。","k":"バイソン","h":"tqffws"},
"G1-03": {"n":"石投げヒヒ","f":"吠える草原の岩丘に棲むヒヒ。ガルウンの子らの投石を真似るうち、今では子らより上手く投げる。","k":"ヒヒ","h":"1mqudfa"},
"G1-04": {"n":"仔ハイエナ","f":"自分の頭ほどの骨をくわえ、決して放さない。負けた夜でも、くっくっと笑う。","k":"ハイエナ","h":"1ac92kt"},
"G1-05": {"n":"草原ハイエナ","f":"決闘場の歓声が聞こえるとどこからか現れ、柵の外をうろつく。終わった戦いの骨まで片付けるのが彼らの役目だ。","k":"ハイエナ","h":"ed549r"},
"G1-07": {"n":"草原ケンタウロス","f":"オークより先に吠える草原を駆けた狩人。一日中風を背に走り、弓を引くのはただ一度。","k":"ケンタウロス","h":"1dfhpwt"},
"G1-08": {"n":"石爪ガーゴイル","f":"ゴルヴァスの背の崖にうずくまる石の獣。翼を広げるまで、オークはただの岩だと思っている。","k":"ガーゴイル","h":"lhsi7o"},
"G1-10": {"n":"石牙の猪","f":"牙が石のように固まった草原の猪。止まり方を知らず、通った跡は耕した畑になる。","k":"イノシシ","h":"mrp24s"},
"G1-11": {"n":"黒曜の槍使い","f":"王座峰の麓で拾った黒曜石を穂先に結んだ。欠けた刃ほど深く刺さる。","k":"マングース","h":"rw1txh"},
"G1-12": {"n":"投石の若巨人","f":"ゴルヴァスの背から生じて百年にも満たない岩の巨人。まだ山を持ち上げる力がなく、岩を投げる。","k":"岩の巨人","h":"1i441mb"},
"G1-13": {"n":"砂利コカトリス","f":"睨んだものを砂利に変える、鶏頭蛇尾の獣。巣の周りがいつも砂利だらけなのはそのためだ。","k":"コカトリス","h":"izr5f5"},
"G1-14": {"n":"突撃ミノタウロス","f":"ガルウン決闘場でオーク十人を突き倒し、ゴルヴァスの目に留まった。今も前に何があるかは、ぶつかってから知る。","k":"ミノタウロス","h":"aw5r3n"},
"G1-15": {"n":"黒曜爪バジリスク","f":"王座峰の麓の黒曜石を噛んで爪を研いだバジリスク。目が合えば固まり、爪にかかれば血が長く止まらない。","k":"バジリスク","h":"1vv0e5s"},
"G1-18": {"n":"オーガの呪術師","f":"地に耳を当て、グロムの一言を待つオーガ。オークより耳が大きいので、最初の音節の半分は聞いたと言い張る。","k":"オーガ","h":"ounjor"},
"G1-19": {"n":"岩背熊の騎手","f":"王座峰の麓で長く眠り、背に岩が刺さった熊。オークを乗せはするが、立ち上がる時は熊が決める。","k":"熊","h":"1xalwnk"},
"G1-21": {"n":"黒曜ケンタウロス弓兵","f":"頭目だけを狙うケンタウロス。倒すたびに弓に刻みを入れ、今や弓は刻みで覆われた。","k":"ケンタウロス","h":"o4e1dd"},
"G1-23": {"n":"戦太鼓のオーガ","f":"熊皮の太鼓を腹に下げたオーガ。太鼓が速まるとオークの息が荒くなり、その腹も一緒に鳴る。","k":"オーガ","h":"uwyanl"},
"G1-24": {"n":"ハイエナの群れ長","f":"一度笑えば散った群れが集まり、二度笑えば敵が散る。","k":"ハイエナ","h":"1w1bnsn"},
"G1-25": {"n":"ゴルヴァスの子","f":"王座峰に地震が多かった年、ゴルヴァスの背から生じた岩の巨人。拳を握るたび、大地も一緒にびくりとする。","k":"岩の巨人","h":"18qgwv4"},
"G1-26": {"n":"戦王トゥルク","f":"岩牙族を率いてノコギリ峠を三度越えた。戻るたびに、群れは大きくなっていた。","k":"剣歯虎","h":"13cde6"},
"G1-27": {"n":"母なる洞窟熊","f":"王座峰の洞窟で子を抱いて冬を越す。春が来れば子より先に穴を出て、前に立ちはだかる。","k":"熊","h":"157wyn4"},
"G1-28": {"n":"草原バイソンの群れ","f":"雷鳴のような音で吠える草原を横切るバイソンの群れ。止まり方は誰も教えず、学ぶ気もない。","k":"バイソン","h":"z718sa"},
"G1-29": {"n":"グロムの岩精霊","f":"大地の大精霊グロムが百年かけて一言を発すると、岩が集まり立ち上がった。その一言が何だったか、岩たちもまだ知らない。","k":"岩の精霊","h":"qut650"},
"G1-32": {"n":"黒曜の巨獣トカゲ","f":"黒曜石の鱗をまとった牛ほどのトカゲ。それが駆けると、草原の草がみな一方へ倒れる。","k":"大トカゲ","h":"k5b84h"},
"G1-33": {"n":"巡礼する岩の巨人","f":"ゴルヴァスの背から王座峰の頂まで歩いて登る岩の巨人。一歩に一年かかるので、オークはその歩みで暦を合わせる。","k":"岩の巨人","h":"194vg4i"},
"G1-34": {"n":"ゴルヴァスのゴルゴン","f":"ゴルヴァスの眠りを覚まそうとする者を石に変える。王座峰の麓に並ぶ石像の多くは、かつて鉱夫だった。","k":"ゴルゴン","h":"1ofqyex"},
"G1-35": {"n":"大地震えのワーム","f":"ゴルヴァスの背の下を掘り進む巨大な虫。王座峰の地震のいくつかは、実はこれのあくびだ。","k":"大地ワーム","h":"1reb06g"},
"G1-36": {"n":"ミノタウロス大族長","f":"ミノタウロスの群れを率いる大族長。彼が止まった場所がその年の戦場になり、オークもあえて他を選ばない。","k":"ミノタウロス","h":"1cmt02u"},
"G1-41": {"n":"盾持ちオーガ","f":"草原の沼の大亀の甲羅を盾にしたオーガ。その陰にオークの末っ子が三人まとめて隠れる。","k":"オーガ","h":"1w634f4"},
"G1-42": {"n":"ゴルヴァスの落鱗","f":"ゴルヴァスが寝返りを打った時、王座峰の麓に落ちた鱗一枚。竜が眠る間も、ひとりでに立ち上がり刃を受け止める。","k":"竜鱗","h":"1ejkdlt"},
"G1-43": {"n":"城壁の岩精霊","f":"グロムの意を受け、岩が壁のように並んだ精霊。オークが退くことを覚えたのは、その壁の陰でだ。","k":"岩の精霊","h":"jnhih3"},
"G2-02": {"n":"苔のコダマ","f":"古木の陰に長く溜まった森の息が、小さな体を得た。踏まれれば砕け、雨が降れば頭をカタカタ鳴らしてまた生える。","k":"コダマ","h":"1yt50kv"},
"G2-03": {"n":"ナマケモノ見習い弓兵","f":"シルヴァニエルの一番低い枝で弓を習う。高い枝に登るには、まだ何年もかかる。","k":"ナマケモノ","h":"1t8968w"},
"G2-04": {"n":"若きドライアド","f":"蔓の巻いた若木から歩み出たばかりのドライアド。誰かが通れば、眠る彼女より先に蔓が目を覚ます。","k":"ドライアド","h":"15wo0jm"},
"G2-05": {"n":"若きトレント","f":"まだ言葉を覚えきれないトレント。代わりに根で大地の震えを聞き取る。","k":"トレント","h":"1v4t7rn"},
"G2-08": {"n":"アナグマの森番","f":"森で倒れた者を木の下に葬るアナグマ。彼が埋めた場所には毎年花が咲く。","k":"アナグマ","h":"149xbh6"},
"G2-09": {"n":"森のサテュロス","f":"落雷を受けた古木の樹皮を盾に担ぐサテュロス。笛を吹いては戦い、戦ってはまた笛を吹く。","k":"サテュロス","h":"149ar81"},
"G2-11": {"n":"カサタケの歩哨","f":"シルヴァニエルの吊り橋の下、日陰に並んで生えたキノコ族。足音だけで森の客かを見分けるが、返事はいつも一晩遅い。","k":"キノコ族","h":"1o5fhaj"},
"G2-13": {"n":"古木の蜘蛛","f":"古木一本をまるごと糸で包み、己の巣とした。敵は最後まで、糸がどの枝から飛んでくるのか分からない。","k":"森蜘蛛","h":"1gsbbuz"},
"G2-15": {"n":"エイレンの角鹿","f":"エイレン大森林の外縁を巡る鹿の群れ。斧の音が聞こえれば、皆がそちらへ角を向ける。","k":"角鹿","h":"1h2lcwj"},
"G2-17": {"n":"ヒキガエル呪術師","f":"苔を噛みながら森の精霊と語らう。その言葉が分かるのは木々だけだ。","k":"苔ヒキガエル","h":"a6fk2g"},
"G2-20": {"n":"シルヴァニエルの虎","f":"盟約の会議が開かれる日、巨樹の都の階段ごとに伏せる。その日は風さえ許しなく通れない。","k":"森の虎","h":"1as8lma"},
"G2-21": {"n":"トレント戦士","f":"年老いたトレントは争いを嫌う。だが森が燃えるのを見たトレントは違う。","k":"トレント","h":"161uz33"},
"G2-22": {"n":"茨森マンドレイク","f":"茨の森の奥、土に半ば埋もれて生きる。引き抜こうとする者はその悲鳴に道を失い、二度と森の外へ出られない。","k":"マンドレイク","h":"1neecpg"},
"G2-23": {"n":"ドリエンの使徒","f":"森の大精霊が抱く記憶を歌に移して伝える。その歌には焼けた森の名も入っている。","k":"ドライアド","h":"pobjys"},
"G2-25": {"n":"ヴェルダンの落ち角","f":"ヴェルダンが首を振ったとき太古林山脈に落ちた角の枝が、根を下ろして立ち上がった。その傍らでは、竜の許しなく落葉一枚動かせない。","k":"竜角の枝","h":"187ophu"},
"G2-26": {"n":"エイレンのコダマ","f":"大森林の真ん中、老木に住むコダマ。トロールたちはその下で生まれその下に葬られるが、コダマはその名を一つも忘れない。","k":"コダマ","h":"1957yax"},
"G2-27": {"n":"ヴェルダンのレーシー","f":"鹿角を戴く森の主。ヴェルダンの森に許しなく入った者は、長く歩いた末に同じ所を巡っていたと知る。","k":"レーシー","h":"krit06"},
"G2-28": {"n":"防壁の根の巨獣","f":"ノコギリ峠の下に根を張って伏せる巨獣。木こりたちは獣とも知らず斧を当て、その場に斧を置いていった。","k":"根の巨獣","h":"1wpnfdm"},
"G2-30": {"n":"棘背のハリネズミ","f":"シルヴァニエルの門前の茂みに住むハリネズミ。盟約が初めて結ばれた日から、同じ場所で丸まっている。","k":"ハリネズミ","h":"ahjw0u"},
"G2-31": {"n":"ドリエンのグリーンマン","f":"森の大精霊ドリエンが抱く記憶が、葉と蔓で体を得た。彼が通った跡には忘れられた花が再び咲く。","k":"グリーンマン","h":"673k75"},
"G2-32": {"n":"太古林の巨木","f":"太古林山脈で世界最初の森と共に育った木。その陰に入ると時が遅くなる。","k":"トレント","h":"ftv59z"},
"G2-33": {"n":"初古木のドライアド","f":"シルヴァロンへの門、始まりの古木から歩み出たドライアド。彼女の傍らでは、今も別の時が流れる。","k":"ドライアド","h":"12d5ry9"},
"G2-34": {"n":"ヴェルダンの角騎士","f":"ヴェルダンの角から落ちた枝が己の角として生えた牡鹿。角の先に毎年新芽が出るのを見て、トロールたちは騎士と呼んだ。","k":"角鹿","h":"e2yo4z"},
"G2-35": {"n":"古木長老会","f":"数百年を経た古木たちが輪になって開く会議。結論一つに季節が何度も巡る。","k":"トレント","h":"1eg2a98"},
"G2-36": {"n":"エイレンの菌糸心臓","f":"大森林の地下をつなぐ菌糸が一つに集まり脈打つ場所。この心臓が止まらぬ限り、森は何度でも育ち直す。","k":"キノコ族","h":"121zafq"},
"G2-41": {"n":"ナナフシ投槍兵","f":"古木の枝を折って作った槍を投げる。外れた槍は地に刺さり、そのまま根を下ろす。","k":"ナナフシ","h":"mwp720"},
"G2-42": {"n":"毒棘スズメバチ群","f":"茨の森の奥深くに巣を作ったスズメバチの群れ。トロールでさえその巣は避けて通る。","k":"スズメバチ","h":"ruk93h"},
"G2-43": {"n":"落雷の憤怒樹","f":"落雷に半身を焼かれた古木が目覚めた。以来、火の匂いがするものはすべて壊して回る。","k":"トレント","h":"1ex8kqp"},
"G3-01": {"n":"潟湖の見習い巫女","f":"セレネアの潟湖で初めての歌を習う巫女。まだ声は震えるが、水はその震えまで歌い返す。","k":"アマガエル","h":"uj7ikt"},
"G3-02": {"n":"水滴ウンディーネ","f":"泉から跳ね出た小さなウンディーネ。巫女の掌でしばし休み、また水へ還る。","k":"ウンディーネ","h":"18n8iyk"},
"G3-03": {"n":"潟湖の子イルカ","f":"大人の目を盗んで潟湖の外の海まで泳ぎ出る。帰るときはいつも光る何かをくわえている。","k":"イルカ","h":"jfyho2"},
"G3-04": {"n":"真珠貝の番人","f":"潟湖の入口の底に座る大きな貝。引き潮でもその場を離れない。離れる足もない。","k":"真珠貝","h":"mvt1gz"},
"G3-06": {"n":"波のタツノオトシゴ","f":"波に乗ってセレネアの便りを運ぶ。その尾は海路の先の遠い地まで届く。","k":"タツノオトシゴ","h":"11i0kwz"},
"G3-07": {"n":"銛持ちラッコ","f":"珊瑚の間を縫って銛を投げるラッコ。巫女たちが捨てた銛を拾って使ううち、巫女より上手くなった。","k":"ラッコ","h":"14ialhg"},
"G3-08": {"n":"波のこだま","f":"巫女たちが歌ったマレンシアの歌が潟湖を一巡りして体を得た。その波に触れた傷は音もなく閉じる。","k":"こだま","h":"t4tm9g"},
"G3-09": {"n":"セレネアのナーガ兵","f":"潟湖に浮かぶ神殿都市の橋の下でとぐろを巻いて守るナーガ。その槍は水を含み、いつも冷たい。","k":"ナーガ","h":"tv7r32"},
"G3-10": {"n":"幼いセルキー","f":"まだ一人で皮を脱げない幼いセルキー。巫女たちは毎朝、岩に掛かったその皮を見ぬふりをする。","k":"セルキー","h":"1smbb87"},
"G3-11": {"n":"潮占いのタコ","f":"満ち引きの位置を八本の腕で一度に押さえ、明日を占う。タコが墨を吐けば、その日は船を出さない。","k":"タコ","h":"lneytv"},
"G3-12": {"n":"珊瑚甲羅の亀","f":"甲羅に珊瑚が育つウミガメ。割れた所は翌年、より硬い珊瑚に覆われる。","k":"ウミガメ","h":"1eu6tp7"},
"G3-14": {"n":"潮の鮫戦士","f":"満ち潮のように押し寄せ、引き潮のように退く鮫族の戦士。敵が追ってきた瞬間、また満ち潮になる。","k":"鮫族","h":"15me1dn"},
"G3-15": {"n":"ネリアの精霊","f":"水の大精霊から分かれた小さな流れ。器によって笑いもし、怒りもする。","k":"ウンディーネ","h":"ssciw7"},
"G3-16": {"n":"近衛タツノオトシゴ","f":"巫女長の傍らを守る大きなタツノオトシゴ。歌が終わるまで尾を珊瑚に巻き、一寸も退かない。","k":"タツノオトシゴ","h":"2kgi65"},
"G3-17": {"n":"潟湖の癒しジュゴン","f":"潟湖の温かな水に棲むジュゴン。傷ついた者を背に乗せて一巡りすれば、死にかけた者も息を整える。","k":"ジュゴン","h":"1y4pksx"},
"G3-18": {"n":"水柱の珊瑚精霊","f":"潟湖の珊瑚礁が目覚めて精霊になった。枝を一度掲げれば海が立ち上がり、崩れるときは敵も共に流される。","k":"珊瑚の精霊","h":"1yytv9e"},
"G3-19": {"n":"セレネア巫女長","f":"泉の巫女団を率いる巫女。彼女が歌い出すと、潟湖の波はみな同じ向きに伏す。","k":"白鯨","h":"1r7sycn"},
"G3-24": {"n":"渦潮ケルピー","f":"たてがみを一振りすれば水が渦を巻き始める水馬。その背に乗った者は底まで引きずり込まれる。","k":"ケルピー","h":"38izgh"},
"G3-27": {"n":"海溝のカブトガニ","f":"タラクス海溝の入口で、ウルボアが上る道を守る。巨人たちが横たわる前から今と同じ姿で生きていた。","k":"カブトガニ","h":"1791ddm"},
"G3-28": {"n":"潟湖の子守歌","f":"海の底で眠るタラクスを寝かしつける歌の一節が、潟湖で体を得た。それが通った水辺では死者も静かに海へ還る。","k":"子守歌","h":"1q4r80c"},
"G3-29": {"n":"ネリアの顕現","f":"形なく流れていた水の大精霊が、しばし姿を借りた。その姿は見る者によって違う。","k":"ウンディーネ","h":"1b2x7ek"},
"G3-32": {"n":"深海の竜宮王","f":"深い海の闇に玉座を置くリュウグウノツカイ。彼が水面に上る日は、海全体が息を潜める。","k":"リュウグウノツカイ","h":"jz0e6x"},
"G3-33": {"n":"深海のクラーケン","f":"タラクスの鼓動が速まるほど、海溝から高く上ってくる。人魚はその触手を見ると、歌を一節長く歌う。","k":"クラーケン","h":"12k8jy3"},
"G3-34": {"n":"マレンシアの王蟹","f":"マレンシアの前で鋏を掲げて誓った王蟹。その誓いは海のように長く記憶され、鋏はそれより硬い。","k":"タラバガニ","h":"16ztt8l"},
"G3-36": {"n":"泉の大潮","f":"泉の巫女団が一度も止めなかった歌に満ち潮が応え、体を得た。それが宿る泉は日照りにも涸れない。","k":"潮の精霊","h":"1hqwixm"},
"G3-41": {"n":"突撃シャチ","f":"潮流を背に一気に敵陣へ食い込むシャチ。陸では動けないが、その前に戦いは終わる。","k":"シャチ","h":"mqddrl"},
"G3-42": {"n":"津波の海蛇","f":"津波に乗ってくる海蛇。その後に残るのは濡れた砂と散らばった盾だけだ。","k":"海蛇","h":"p7wxrz"},
"GN-B3-1": {"n":"雷の針","t":"残り体力が最も低い相手ユニット2体の体力−2 −1C。","f":"ヴォルタリウム工房の銅の針は最も弱い脈を探して刺さる。耐えていた者はその一針で崩れる。","b":"{敵体力最小2} ♥−2 −1C","h":"1tc61jy"},
"GN-B3-2": {"n":"雷鳴砲撃","t":"相手の先頭ユニットの体力−4。相手ユニット全体の体力−1 −1C。","f":"雷鳴高原の蓄電塔が一斉に放電する。先頭を貫いた霹靂が地を伝い後ろまで広がる。","b":"{敵前1体} ♥−4|{敵全体} ♥−1 −1C","h":"dzpktn"},
"HA1-1": {"n":"スリ","t":"自分の手札の一番左のカードと相手の手札の一番左のカードを入れ替え、カードを1枚引く。","f":"ノクタールの市場では握手する手にも用心せよ。握らせたものと持ち去ったものは、いつも違う。","b":"{手札} 一番左同士を交換|カードを1枚引く","h":"18krgs2"},
"HA1-2": {"n":"指先の呪い","t":"相手の手札の最初のユニットに[恐怖 3]。そのユニットが戦場に出ると、最初の戦闘開始時に発動する。","f":"指先で軽くかすめただけだった。それ以来、相手陣営の兵がひとり、ずっと咳が止まらない。","b":"{敵手札} 最初のユニット [恐怖 3]|戦場に出ると発動","h":"1p5he7x"},
"HA1-3": {"n":"呪いの伝染","t":"相手の手札の前のユニット2枚に[疫病 2]。戦場に出ると最初の戦闘開始時に発動し、両隣のユニットに[疫病 1]が移る。","f":"呪いはひとりから始まり、兵舎全体に広がる。まだ戦場に立ってもいない者たちの剣まで重くなる。","b":"{敵手札} 前のユニット2枚 [疫病 2]|戦場に出ると発動","h":"2vxc2k"},
"HA3-1": {"n":"援護後退","t":"味方先頭ユニットが最後尾へ下がる(後退)。相手先頭ユニット2体の攻撃−2。","f":"前列が退く間、後列の矢が敵の腕を縛る。風は退く側の背を押してくれる。","b":"{味方前1体} 最後尾へ後退|{敵前2体} ⚔−2","h":"14vznug"},
"HA3-2": {"n":"偵察","t":"相手手札の最初のユニットの攻撃−2(この対戦中ずっと)。呪い免疫の攻撃は削られない。カードを1枚引く(ライフ消費なし)。","f":"風の斥候が敵の陣幕から持ち帰った知らせ。最初に出てくる敵の腕を先に縛っておく。","b":"{敵手札} 最初のユニット ⚔−2 (対戦中)|{自分} 1枚引く","h":"1tpuak1"},
"HB1-1": {"n":"弾薬庫奇襲","t":"ライフ2を払い、相手の手札から無作為に1枚を焼却する。","f":"真夜中、ゴブリン数匹が敵の弾薬庫に忍び込んだ。帰った者は少なかったが、敵の夜はもっと短かった。","b":"{代償} ライフ2|{敵の手札} 無作為1枚焼却","h":"170j7ou"},
"HB3-1": {"n":"予知","t":"カードを1枚引く(ライフ消費なし)。手札の一番左のカードをデッキの一番下へ。","f":"雷が落ちる前の空気の震えを読むノームの技。彼らは次の手を既に知って動く。","b":"カード1枚引く|一番左のカード → デッキ最下","h":"jqjhwn"},
"I2-2": {"n":"牙の狂戦斧","f":"岩牙の狂戦士たちの両刃斧。守りを捨て、一撃に懸ける。","h":"lrrdwa"},
"I2-3": {"n":"影の投げ短剣","f":"ノクタールの刺客が袖に隠し持つ短剣。装備した瞬間に投げる。","h":"hie98i"},
"I3-2": {"n":"エラドの塔盾","f":"暁城の門の騎士が使う塔盾。どんな呪いも、盾を掲げる手を下ろさせられない。","h":"5itqm6"},
"I3-3": {"n":"シルヴァニエル長弓","f":"森番の長弓。遠くから射て退き、反撃を受けない。","h":"q6xhf"},
"IA1-1": {"n":"血の誓約の護符","f":"己の血で名を書いた護符。代償の分だけ力を与える。","h":"kr3n1g"},
"IA1-2": {"n":"黒曜の短剣","f":"ノクタールの黒曜石の短剣。斬った傷は塞がらず、戦いの間ずっと血を流す。","h":"qoy1j5"},
"IA1-3": {"n":"呪い人形","f":"相手の髪を入れた人形。針を刺すたびに悲鳴が聞こえる。","h":"1pn0667"},
"IA1-4": {"n":"深淵の仮面","f":"被った瞬間に顔が消える仮面。斬った者の血でその顔を描き直す。","h":"1h2act9"},
"IA1-5": {"n":"契約書の原本","f":"モルカスと結んだ契約書の原本。持ち主が血で代価を払うたび、署名した者の剣が重くなる。","h":"ycc5ws"},
"IA2-1": {"n":"押収した黒曜剣","f":"審問官が魔族から取り上げた黒曜石の剣。浄化の儀が終わるまでだけ借りて使う — 斬った傷はそれまで癒えない。","h":"14k8amd"},
"IA2-2": {"n":"銀の盾","f":"光を照り返す銀の盾。","h":"z6dl1x"},
"IA2-5": {"n":"ソランテの聖剣","f":"太陽神ソランテが最初の騎士に授けた聖剣。","h":"1txc3ir"},
"IA3-3": {"n":"弓士会の外套","f":"風がまとわりつく嵐の塔弓士会の外套。飛来した矢が裾で道に迷う。","h":"1bf32c1"},
"IA3-4": {"n":"旋風の矢筒","f":"矢を抜くたびに風が吹く。風に乗った矢は自ら鎧の隙間を探す。","h":"1ys6vr9"},
"IA3-5": {"n":"ベルミルの長弓","f":"星を読む神ベルミルの長弓。届かぬ場所から射て、矢が刺さる時、射手はもうそこにいない。","h":"2hxree"},
"IA3-6": {"n":"雷羽の矢","f":"嵐の塔の頂で集めた雷を羽根に巻いた矢。射るたびに雷が共に飛ぶ。","h":"1bw0nlx"},
"IB1-1": {"n":"火縄銃の銃床","f":"フォルタンの砲手が弾切れの時に振るう銃床。殴られると長く痛む。","h":"7gmtj8"},
"IB1-2": {"n":"火種の弾帯","f":"腰に巻いた小さな火薬樽。芯に火をつけて投げる。","h":"46gk9v"},
"IB1-3": {"n":"ラッパ散弾銃","f":"銃口がラッパのように開いたフォルタンの散弾銃。毎ターン一発ずつばら撒く。","h":"1nbdh5g"},
"IB1-4": {"n":"砲手の望遠鏡","f":"コグヘイヴンのレンズ職人の望遠鏡。弱点を突けば、立っているのがやっとの力しか残らない。","h":"lj60oz"},
"IB1-5": {"n":"ドルマクの火炎砲","f":"巨人ドルマクの心火の欠片を装填した携帯火砲。遠くから撃って退き、撃つたびに地面を焦がすだけだ。","h":"89wr0x"},
"IB2-1": {"n":"リベットの刻印","f":"ゴーレムの装甲板を繋ぐリベット形の刻印。一度打てば抜けない。","h":"f9vf7s"},
"IB2-2": {"n":"鋼の装甲板","f":"ドゥルクハイム工房の標準装甲板。重いが確かだ。","h":"jl0ppa"},
"IB2-4": {"n":"オートマトンの心臓","f":"オートマトンの動力炉。最初の衝撃は歯車が受け止める。","h":"b5tu8x"},
"IB2-5": {"n":"鉄の盾","f":"ゴーレムの掌を外して作った盾。","h":"1xgi8am"},
"IB2-6": {"n":"ゴーレム核","f":"巨大ゴーレムから取り出した核。体に刻めば歩く要塞となる。","h":"1mbwbuv"},
"IB3-1": {"n":"銅のコイル","f":"手首に巻く銅のコイル。巻いた手で呼ぶ雷は一筋太い。","h":"59vuo5"},
"IB3-2": {"n":"蓄電の籠手","f":"充電されると拳が光る籠手。充電されるかはその日の運だ。","h":"3cpkie"},
"IB3-3": {"n":"避雷の杖","f":"先に避雷針をつけた杖。集まった雷がひとりでに弾ける。","h":"1bl7nvk"},
"IB3-4": {"n":"雷の瓶","f":"雷を閉じ込めたガラス瓶。割れる瞬間が一番明るい。","h":"rw8d5b"},
"IB3-5": {"n":"学術院の法典","f":"ヴォルタリウム学術院の分厚い法典。公式一行が雷をもう一筋呼ぶ。","h":"jic7ix"},
"IG1-1": {"n":"狩人の爪","f":"初めての獲物の爪を手の甲に縫い付ける。","h":"1t8mx8j"},
"IG1-3": {"n":"激怒の刺青","f":"血が滾ると赤く光る刺青。守りなど忘れる。","h":"1hblkn4"},
"IG1-4": {"n":"岩呪のトーテム","f":"呪術師が背負う小さな岩のトーテム。呪いは遠くからかけ、返す拳は届かない。","h":"shuar"},
"IG1-6": {"n":"牙の戦斧","f":"族長の戦斧。ひと振りで前に立つ者を越え、その後ろの者まで割る。","h":"1e98wer"},
"IG2-1": {"n":"棘の刺青","f":"蔓の棘をかたどった刺青。殴った側が先に血を見る。","h":"19qp762"},
"IG2-2": {"n":"樹皮の刻印","f":"古木の樹皮を写した刻印。年を経るほど厚くなる。","h":"8j61v9"},
"IG2-3": {"n":"苔の護符","f":"古い岩の苔を編んだ護符。","h":"k0ieab"},
"IG2-5": {"n":"生命の種","f":"心臓の傍らに植える種。枯れない体になる。","h":"7e58tq"},
"IG2-6": {"n":"ヴェルダンの根","f":"森の竜ヴェルダンの根が血管に沿って育つ。伸びた根は鎧の隙間に割り込み、こじ開ける。","h":"sch8z0"},
"IG3-1": {"n":"貝の護符","f":"波が最初に打ち上げた貝で作った護符。","h":"gkwrbz"},
"IG3-2": {"n":"泉の水瓶","f":"泉の巫女が祝福した水瓶。飲めば傷が閉じる。","h":"y20n21"},
"IG3-3": {"n":"珊瑚の短剣","f":"赤珊瑚を削った短剣。投げれば潮のように曲がる。","h":"1g3evf2"},
"IG3-4": {"n":"真珠の聖標","f":"深海の真珠をはめた聖標。胸に付ければ海が一息を吹き込む。","h":"1cua12l"},
"IG3-5": {"n":"水滴の宝珠","f":"水一滴を閉じ込めた宝珠。水はどんな隙間にも染み込む。","h":"138n00x"},
"IG3-6": {"n":"潟湖の鱗","f":"セレネアの潟湖の底から引き上げた青い鱗。運が良ければ刃が滑る。","h":"17z32j7"},
"IG3-8": {"n":"潮の三叉槍","f":"満ち潮と引き潮を呼ぶ三叉槍。","h":"jod7vt"},
"IR-A1": {"n":"ノクタール血仮面","f":"深淵契約団の処刑人が被る仮面。被った者は斬った傷から流れる血を己の息として吸い込む。","h":"15sn8vn"},
"IR-A2": {"n":"ソランテの誓いの盾","f":"暁城エラドの騎士が誓いを終えた日に受け取る盾。誓いを守る間、最初の刃は光に滑る。","h":"n7s8vi"},
"IR-A3": {"n":"星文字の矢","f":"イサクが解読した星の文字を、針の塔の射手が矢柄に刻んだ。飛ぶ間、風が向きを変えて的を追う。","h":"1qhphj3"},
"IR-B1": {"n":"名手の火縄銃","f":"フォルタン砲兵団で百発撃って百発当てた者にだけ与えられる銃。銃床には当てた数だけ刻みがある。","h":"zlug4e"},
"IR-B2": {"n":"アダマント装甲板","f":"眠る巨人の骨が固まった灰色の金属を、ドゥルクハイムで薄く延ばしたもの。割れないというのは誇張ではない。","h":"14rhl55"},
"IR-B3": {"n":"銅の避雷棒","f":"ヴォルタリウムの避雷塔の先を切って作った杖。雷は握る手ではなく狙った先に落ちる。","h":"p7f36c"},
"IR-G1": {"n":"灰鬣の刺青","f":"灰鬣のカルノの決闘を見届けた者だけが刻める刺青。刻んだ日から、刃先が急所を探す。","h":"1ip46hv"},
"IR-G2": {"n":"初古木の樹皮","f":"シルヴァニエルの始まりの古木が自ら落とした樹皮。斬ろうとする刃はすべて棘となって返る。","h":"5qtvyb"},
"IR-G3": {"n":"ネリアの水滴","f":"水の大精霊ネリアがセレネアの泉に落とした一滴。宿った器の傷から洗う。","h":"83tquu"},
"M2-1": {"n":"牙の刺青","f":"岩牙族が初狩りを終えて前足に刻む牙の刺青。この前足はまず鎧を裂く。","h":"1tmi9r4"},
"M3-1": {"n":"ゴーレムのルーン","f":"ドゥルクハイムのルーン工がゴーレムの心臓に刻むルーン。刻まれた体はどんな呪いでも衰えない。","h":"1g22t9j"},
"M4-1": {"n":"トレントの年輪","f":"千年トレントの年輪を体に刻む。毎年一重ずつ厚くなる。","h":"v1xftb"},
"MA-01": {"n":"恐怖の刃","t":"相手の先頭ユニット2体に[恐怖 3]。","f":"刃は肉を斬らない。その影がかすめた者は、翌朝、柄を握る手が震える。","b":"{敵前2体} [恐怖 3]","h":"nd6ezj"},
"MA-02": {"n":"ソランテの加護","t":"味方の先頭ユニットに[障壁]。そのユニットの防御−2。","f":"暁の母が先に立つ者を包む。加護を受けた者は鎧を脱ぎ、光だけを信じる。","b":"{味方前1体} [障壁] ⛨−2","h":"11nix3l"},
"MA-03": {"n":"無力化","t":"相手先頭ユニットの攻撃−5。","f":"針の塔で最初に学ぶ防御の呪文。相手の腕から力が風のように抜けていく。","b":"{敵前1体} ⚔−5","h":"r3hiui"},
"MA-04": {"n":"血の共鳴","t":"相手ユニットのうち攻撃が最も高いユニット1体の体力−(このターン捧げた生贄+2)。","f":"流した血は消えない。深淵の底に染みて響き、最後の呪文に乗って一気に噴き出す。","b":"{敵攻撃最高1体} ♥− 捧げた生贄+2","h":"1apodnb"},
"MA-05": {"n":"血の天秤","t":"[生贄 3] 相手ユニットのうち攻撃が最も高いユニット1体を破壊する。","f":"モルカスの天秤の片側に己の血を載せる。向かいで最も重い者が運び出される。","b":"{生贄} ライフ 3|{敵攻撃最高1体} 破壊","h":"mue1qv"},
"MA-07": {"n":"ヒット&アウェイ","t":"味方先頭ユニット2体の攻撃+2。先頭ユニットは最後尾へ下がり(後退)、このターン[遠隔]。","f":"射て、退き、また射る。ハイエルフの射手は刃の届く距離に長くとどまらない。","b":"{味方前2体} ⚔+2|{味方前1体} 最後尾へ後退 [遠隔]","h":"12cq9ta"},
"MA-08": {"n":"誓いの固め","t":"味方の先頭ユニット2体の体力+2 +1C。その2体に[呪い免疫]。","f":"誓いを鉄のように固めて身に刻む。固い誓いの上には、どんな呪いも染みない。","b":"{味方前2体} ♥+2 +1C|{味方前2体} [呪い免疫]","h":"qnhs0m"},
"MA-09": {"n":"地獄の業火","t":"相手ユニットのうち防御が最も高いユニット1体の防御Dがこのターン−Dになり、体力−D。防御が厚いほど熱く燃える。","f":"ノクタールの業火は鎧を薪にして燃える。厚い鉄ほど長く、熱く、消えることがない。","b":"{敵⛨最高1体} ⛨ D → −D · ♥−D","h":"6fubd2"},
"MA-10": {"n":"殉教の誓約","t":"このターン、味方ユニットが倒れるたびに、その両隣の味方ユニットに[障壁]。","f":"誓った騎士は倒れる瞬間、最後の光を隣の兄弟に渡す。その光は次の刃を一度、代わりに受け止める。","b":"{味方} 倒れるたび|両隣の味方 [障壁]","h":"12j1tgq"},
"MA-11": {"n":"とどめの矢","t":"相手ユニットのうち残り体力が最も低い2体の体力−3。","f":"よろめく敵を選ぶのも射手の目だ。最後の一矢はいつも最も弱いところを探し当てる。","b":"{敵体力最低2体} ♥−3","h":"xhg53"},
"MA-14": {"n":"暁の解放","t":"溜めた[暁光]に、自分のライフが相手より少ない分を加えてすべて解き放ち、攻撃が最も高い相手ユニットから順にその分の体力を削る。倒せば残りは次のユニットへ、それでも残れば自分のライフに戻る。","f":"夜通し積もった光が一度に東の空を裂く。最も鋭い刃を持つ者から光に目を焼かれ、残った光は疲れた者たちの傷を覆う。","b":"[暁光] + ライフ差 → {敵 ⚔高い順} ♥−|残りは自分のライフ +","h":"fm0jvy"},
"MA-16": {"n":"血の盟約","t":"[生贄 3] 味方全体の攻撃+3、[吸血]。","f":"皆が一杯の血を分け合って飲んだ。その夜、ノクタールの軍勢は恐れを失った。","b":"{生贄} ライフ 3|{味方全体} ⚔+3 [吸血]","h":"1kkrmkr"},
"MB-01": {"n":"散弾砲撃","t":"敵ユニット1体の体力−2 −1C×2。","f":"鉄球を一袋丸ごと大砲に詰めた。雨ではなく鉄の降る音が野を覆った。","b":"{敵1体} ♥−2 −1C×2","h":"7uhl13"},
"MB-02": {"n":"リベット補強","t":"味方ユニット2体の体力+2。","f":"緩んだ継ぎ目ごとに新しいリベットを打つ。ドワーフは直せるものを捨てない。","b":"{味方2体} ♥+2","h":"17ws776"},
"MB-03": {"n":"蓄電放出","t":"相手の先頭ユニットの体力−1 −1C×3。","f":"瓶に溜めた雷を一度に解き放った。閉じ込められた時間の分だけ怒っていた。","b":"{敵前1体} ♥−1 −1C×3","h":"bfdgi3"},
"MB-04": {"n":"導火線","t":"敵の先頭ユニットの体力−1、火傷3。","f":"火のついた芯が地を這い、敵の足元まで行く。爆ぜるのはずっと後——ゴブリンはその待ち時間を好む。","b":"{敵前1体} ♥−1|火傷3","h":"18gweaf"},
"MB-05": {"n":"火種撒き","t":"敵の先頭ユニット2体に[火傷 2]。","f":"ゴブリンは砲弾の代わりに火種の袋を投げる。爆音はないが、翌朝の敵陣は煙で目覚める。","b":"{敵前2体} 火傷2","h":"ck0frb"},
"MB-06": {"n":"放熱鉄壁","t":"敵ユニット3体の体力−1。味方ユニット3体の防御+1。","f":"灼けた鉄板を壁のように立てて熱を防ぐ。迫る敵は、その壁が放つ熱に先に焼かれた。","b":"{敵3体} ♥−1|{味方3体} ⛨+1","h":"14cjsws"},
"MB-07": {"n":"過負荷回路","t":"味方ユニット3体の攻撃+1 +1C。","f":"安全装置をすべて外し、回路に限界まで雷を流した。焦げ臭ければ成功だ。","b":"{味方3体} ⚔+1 +1C","h":"1u0gclf"},
"MB-08": {"n":"装甲固定","t":"味方の先頭ユニット2体の防御+1、体力+1。その2体に[呪い免疫]。","f":"全装甲板のネジを最後まで締めた。呪いが入り込む隙は、継ぎ目一つ残っていない。","b":"{味方前2体} ⛨+1 ♥+1|{味方前2体} [呪い免疫]","h":"83y2ok"},
"MB-11": {"n":"落雷照準","t":"攻撃が最も高い相手ユニット1体を破壊。味方ユニット1体の体力−1。[装填 2]","f":"ノームは雷の落ちる場所を計算する。ただ少し外れると、すぐ隣が焼ける。","b":"{敵攻撃最大1体} 破壊|{味方1体} ♥−1","h":"1gxmiub"},
"MC-01": {"n":"伏せる狼","t":"味方ユニット全体の攻撃がこのターン1になり、変化しない。減った攻撃の合計だけ、相手ユニット全体の攻撃−(このターン)。","f":"狼の群れが牙を隠し、地に身を伏せる。飛びかかった敵は、どこを噛めばいいか分からずためらう。","b":"{味方全体} ⚔ 1(このターン固定)|{敵全体} ⚔ −(減った合計)","h":"1t1jvel"},
"MC-02": {"n":"研ぎ澄まし","t":"味方の先頭ユニット2体の攻撃+4。","f":"砲撃の前、ゴブリンは銃剣を砥石で研ぐ。使わずに済むよう願いつつも、刃だけはいつも立てておく。","b":"{味方前2体} ⚔+4","h":"1ab9yh1"},
"MC-03": {"n":"逆さの水路","t":"敵ユニットを防御と体力の合計が高い順に先頭から並べ直す(魔法の枠はそのまま)。味方先頭ユニットにこのターン[治癒 1]。","f":"水路が変われば、船は意に反して流される。硬い者は前へ押し出され、素早い者は後ろへ押されて剣を抜く暇を失う。","b":"{敵ユニット} 防+体の順に並べ直す|{味方前1体} [治癒 1]","h":"1vw0a50"},
"MC-04": {"n":"祈願","t":"味方先頭ユニット2体の体力+1 +1C。味方先頭ユニットにこのターン[浄化]。","f":"巫女たちが水辺にひざまずいて祈る。潟湖の水が静かに満ち、先に立つ者たちの傷を濡らす。","b":"{味方前2体} ♥+1 +1C|{味方前1体} [浄化]","h":"15hmpbf"},
"MC-05": {"n":"幻覚","t":"相手の先頭ユニットが幻覚に陥り、すぐ後ろの味方ユニットを自分の攻撃で打つ。","f":"ノクタールの霧を吸った者には、傍らの戦友が魔族に見える。剣を振り下ろしてから、ようやくその顔に気づく。","b":"{敵前1体} すぐ後ろの味方を自分の⚔で打つ","h":"1hn2i79"},
"MC-06": {"n":"武装解除","t":"相手ユニット全体の攻撃−1。相手先頭ユニット2体はさらに攻撃−2。","f":"風が柄をねじり、手から引き剥がす。前列に立つ敵ほど遠くへ飛んでいく。","b":"{敵全体} ⚔−1|{敵前2体} さらに⚔−2","h":"sa55uc"},
"MC-08": {"n":"波紋","t":"敵ユニット1体の体力−2。相手の先頭ユニット2体は[障壁]·[棘]·[呪い免疫]·[守護]を失い、さらに体力−2。","f":"一筋の雷が波のように広がる。鉄と魔法の殻が、その震えに一枚ずつ剥がれた。","b":"{敵1体} ♥−2|{敵前2体} 能力解除 ♥−2","h":"10tm7cp"},
"MC-11": {"n":"沈黙","t":"敵の先頭ユニット2体の攻撃が0になり、体力−3。","f":"森が息を止めると、あらゆる音が消える。敵は剣を振り上げる術さえ忘れる。","b":"{敵前2体} ⚔=0 ♥−3","h":"178iq6z"},
"MC-14": {"n":"鎧ごと巻き締め","t":"敵ユニット全体が自身の防御と同じダメージを受け、このターン防御が0になる。","f":"無数の蔓が鎧ごと敵を巻き締める。捩じれて剥がれた鎧は苔の下へ沈んでいく。","b":"{敵全体} ダメージ = ⛨|その後 ⛨ 0","h":"1l7jbqf"},
"MC-16": {"n":"不信の砲火","t":"敵ユニット全体の体力−1。敵の先頭ユニット2体はさらに体力−3。","f":"神に祈るくらいなら火薬をもう一握り詰める。それが巨骨の知る唯一の祈りだ。","b":"{敵全体} ♥−1|{敵前2体} さらに♥−3","h":"1lqkfkk"},
"MG-01": {"n":"牙の突撃","t":"味方ユニット2体の攻撃+1 +1C。","f":"後ろに控えたオークが牙をむく。前列を跳び越え、真っ先に届くのは彼らだ。","b":"{味方2体} ⚔+1 +1C","h":"1pmnmxp"},
"MG-03": {"n":"泉の一口","t":"味方先頭ユニットにこのターン[治癒 2]。","f":"セレネアの泉の水を一口飲む。喉を下った水が疲れた体をまた目覚めさせる。","b":"{味方前1体} [治癒 2]","h":"1fvbw6s"},
"MG-04": {"n":"怨恨の一撃","t":"味方ユニット1体の攻撃+(自分の焼却場のユニットカード枚数)。","f":"倒れた兄弟の名をひとつ呼ぶごとに拳が重くなる。最後の名で、その拳が落ちる。","b":"{味方1体} ⚔+(焼却場ユニット数)","h":"ui39br"},
"MG-05": {"n":"大地震動","t":"敵ユニット4体の体力−1。味方ユニット3体の攻撃+1C。","f":"オークが一斉に足を踏み鳴らすと大地が鳴る。遠くの敵ほど、その揺れに膝が折れる。","b":"{敵4体} ♥−1|{味方3体} ⚔+1C","h":"1odrh6u"},
"MG-08": {"n":"根の束縛","t":"敵ユニット3体の攻撃−2 −1C×2。","f":"地中から根が伸び、足首に絡みつく。後ろで機を窺っていた者たちが先に捕まる。","b":"{敵3体} ⚔−2 −1C×2","h":"1ajxt73"},
"MG-10": {"n":"古木の帳","t":"味方ユニット1体の防御+1、[棘 1 +1C×2]。","f":"老いた古木が枝を垂らして帳を張る。その帳を裂こうとする手は棘に刺される。","b":"{味方1体} ⛨+1 [棘 1] +1C×2","h":"4rslpx"},
"MG-11": {"n":"裏返る水鏡","t":"敵の先頭からユニット2体の攻撃と防御を入れ替える([呪い免疫]ユニットは除く)。","f":"水鏡に映る戦士は、剣ではなく盾を持つ自分を見る。振るおうとした力は殻のように固まり、刃先が鈍る。","b":"{敵前2体} ⚔ ↔ ⛨","h":"37s9u5"},
"MG-12": {"n":"泉の祝福","t":"敵ユニット全体のコインが裏になる(コイン確率−50%、すでに決まったコインはそのまま)。味方先頭ユニットの体力+2 +1C。","f":"泉の巫女が祝福の水を撒く。敵の幸運は洗い流され、味方の傷は癒える。","b":"{敵全体} コイン裏|{味方前1体} ♥+2 +1C","h":"1s9r8n9"},
"MG-13": {"n":"骨砕き","t":"防御0の相手ユニットのうち攻撃が最も高い1体の防御と体力を入れ替える(体力0になり倒れる)。","f":"鎧を剥がれた者に残るのは骨だけだ。ゴルヴァスの拳はその骨を岩のように砕く。","b":"{敵 防御0 攻撃最高1体} ⛨ ↔ ♥ (倒れる)","h":"16hscmv"},
"MG-14": {"n":"森の重み","t":"味方ユニットの残り体力の合計だけ、敵の先頭ユニットから攻撃 → 防御 → 体力の順に削る(攻撃・防御はこのターン)。削り切って倒したら、残りは次のユニットへ。","f":"森全体が一方へ傾く。耐えてきた体の重みがそのまま降り注ぎ、前を塞ぐものから順に押し潰される。","b":"{敵前から} ⚔ → ⛨ → ♥ 削る|量 = {味方} ♥ 合計 · 余りは次へ","h":"9u8k7b"},
"MG-15": {"n":"癒しの潮","t":"味方ユニット全体にこのターン[治癒 1]。味方全体の体力+1。","f":"温かな満ち潮が戦場を濡らす。水が引くと、倒れていた者たちが一人また一人と立ち上がる。","b":"{味方全体} [治癒 1] ♥+1","h":"1n1ync8"},
"MG-16": {"n":"大地崩壊","t":"相手ユニット全体の体力−3、味方ユニット全体の体力−2 −1C。","f":"大地がまるごと抜け落ちる。オークは共に落ちながらも笑う。先に立った方が勝つのだから。","b":"{敵全体} ♥−3|{味方全体} ♥−2 −1C","h":"omx1t6"},
"NA1-1": {"n":"影の強奪","t":"この魔法と同じマス番号に置かれた相手のカードを奪い、自分の戦場の最後尾に置く。ユニットならこのターン自分のユニットとして戦い、生き残れば戦闘終了時に相手の戦場の最後尾へ戻る。裏向きの魔法なら自分の魔法として発動する。","f":"敵が置いたものの影を掴み、こちらへ引き寄せる。束の間借りたものは、戦いが終われば散って戻る。","b":"{敵同じマス} カードを奪う|マス=この魔法のマス · 自分の最後尾に置く|ユニットはこのターンだけ味方 · 生きれば返す","h":"3jsrwi"},
"NA2-1": {"n":"救済の光","t":"味方の先頭ユニットよりレベルが低く特殊能力を持つ相手ユニットのうち、先頭の1体がこのターン暁城の小聖像(攻撃0 · 防御2 · 体力4、能力なし)になる。","f":"光が降りた者は手にした武器を下ろす。目を開けたとき、彼は暁城の広場の小聖像のように固まったまま仲間の前に立っている。","b":"{敵 能力持ち・味方前よりLv低1}|→ 小聖像 0/2/4","h":"qlttg8"},
"NA2-2": {"n":"光の翼","t":"味方の先頭ユニット2体に[障壁]、防御+1。","f":"ソランテの六枚の翼が、先頭に立つ二人を包む。刃先が届く前に、光の羽が先に受け止める。","b":"{味方前2体} [障壁] ⛨+1","h":"1qenbt0"},
"NA3-1": {"n":"裂く風","t":"相手ユニット全体の防御が0になる(このターン)。相手ユニット全体の体力−1。","f":"鎧の継ぎ目だけを選んで食い込む風。過ぎた後、鉄は布のようにぼろぼろになる。","b":"{敵全体} ⛨を0に|{敵全体} ♥−1","h":"99xy2p"},
"NA3-2": {"n":"降り注ぐ矢","t":"相手先頭ユニットを除く相手ユニット全体の体力−3。","f":"先頭の盾の壁の向こうへ矢が雨のように降る。後ろに隠れていた者が先に倒れる。","b":"{敵先頭以外全部} ♥−3","h":"1fcmidf"},
"NA3-3": {"n":"星明かりの連射","t":"[弓]を持つ味方ユニットごとに2ずつ、相手ユニット全体の体力を削る。","f":"弦の音がひとつに重なる瞬間、矢は星明かりとなって空を覆う。弓を持つ手が多いほど星の雨は太くなる。","b":"{敵全体} ♥− 🏹[弓] 味方 × 2","h":"177fjyh"},
"NA3-4": {"n":"風の狩り","t":"相手ユニット全体の体力−3。味方ユニット全体[遠隔]。","f":"ベルミルの針の頂で狩りの角笛が鳴る。その日ハイエルフの矢は風に乗り、刃は一度も彼らに届かない。","b":"{敵全体} ♥−3|{味方全体} [遠隔]","h":"1lvztxp"},
"NB1-1": {"n":"徹甲弾","t":"敵の先頭ユニットに物理ダメージ3。","f":"鉄を幾重にも被せた砲弾。盾を貫いた後も、しばらく転がり続ける。","b":"{敵前1体} 物理ダメージ3","h":"mnz9r8"},
"NB1-3": {"n":"火の風","t":"敵ユニット全体に[火傷 1]。敵の先頭ユニットに[火傷 3]。","f":"ドルマクの心火が息を吐くと、フォルタンの峠に熱風が吹く。その風が過ぎた跡には火種が降りる。","b":"{敵全体} 火傷1|{敵前1体} 火傷3","h":"4byp32"},
"NB2-1": {"n":"過負荷稼働","t":"味方ユニット全体の防御+1。その後、味方ユニット全体の攻撃が自身の防御分上がる。","f":"ボイラーの圧力を限界の先まで上げた。硬い奴ほど激しく駆け出した。","b":"{味方全体} ⛨+1|{味方全体} ⚔ + 自身の⛨","h":"ysa07q"},
"NB2-2": {"n":"盾壁の鬨","t":"味方で最も硬いユニットが先頭に出る([守護])。そのユニットの防御+2。","f":"最も厚い盾を持つドワーフが前に出る。仲間の鬨の声がその背を押した。","b":"{味方} 最も硬い1体|先頭へ [守護] ⛨+2","h":"17k0snr"},
"NB3-1": {"n":"連鎖雷","t":"相手の待機列の先頭から順に体力−2 → −1。","f":"雷は一人では止まらない。先頭を貫き、残った力で次を探しに行く。","b":"{敵先頭から} 順に ♥−2→−1","h":"1k9xfia"},
"NB3-2": {"n":"運命のコイン","t":"このターン、味方ユニットのコイン:+コインはすべて表、−コインはすべて裏。味方の先頭ユニット2体の攻撃+1。","f":"ノームは運さえ計算できると信じる。そのコインは投げる前から表だ。","b":"{味方} コインすべて有利|{味方前2体} ⚔+1","h":"pryb4j"},
"NG1-1": {"n":"激怒","t":"味方ユニット全体の残り体力が1になり、削れた体力だけ攻撃が上がる(このターン)。","f":"傷が深いほどオークの目は赤くなる。倒れる寸前のオークほど恐ろしいものはない。","b":"{味方全体} ♥1に|削れた♥だけ⚔+","h":"1g7h2gu"},
"NG1-2": {"n":"群れの咆哮","t":"相手の先頭ユニットから味方ユニット数だけ、体力−(味方ユニット数×2)。","f":"群れが多いほど遠吠えは大きくなる。草原の果てまで届く咆哮に、敵の隊列が揺らぐ。","b":"{敵先頭から} 味方ユニット数だけ|♥− 味方ユニット数×2","h":"vsffwc"},
"NG2-1": {"n":"根の侵食","t":"防御が1以上の敵ユニットは、それぞれ自身の防御+1のダメージを受ける。","f":"地下を這ってきた根が鎧の隙間ごとに突き出る。素肌の者は、根がそのまま素通りしていく。","b":"{防御ある敵全体} ダメージ ⛨+1","h":"1fag0ir"},
"NG2-3": {"n":"森の再生","t":"味方先頭ユニット2体に[再生 2]。","f":"切られた枝から新芽が出るように、森のものは傷が塞がる。森が生きている限り、彼らは倒れない。","b":"{味方前2体} [再生 2]","h":"mtgp7x"},
"NG3-1": {"n":"荒波","t":"敵ユニット全体の体力−3。","f":"海が荒々しく立ち上がり、陸へ押し寄せる。人魚たちはその波の上で歌う。","b":"{敵全体} ♥−3","h":"127wn31"},
"NG3-2": {"n":"逆流","t":"敵の先頭ユニットと最後尾ユニットの位置を入れ替え、新たな先頭ユニットの体力−2。","f":"潮が突然逆さに流れる。後ろに隠れていた者が押し出され、先頭で波を浴びる。","b":"{敵} 先頭 ↔ 最後尾を入れ替え|{敵前1体} ♥−2","h":"53gvsg"},
"PI-A1": {"n":"モルカスの分銅","f":"沈黙の君主の天秤から外した分銅。握る者の剣は重くなり、天秤が最初の刃の重さを軽くしてくれる。だが握る間、己の傷は癒えない。代価の法則だ。","h":"1uobz1d"},
"PI-A2": {"n":"ソランテの翼羽","f":"暁の母が六枚の翼から抜いて授けた羽一枚。まとう者の防御はその羽の厚みとなり、羽先は刃のように斬って癒えぬ傷を残す。","h":"r0a5op"},
"PI-A3": {"n":"ベルミルの星弦","f":"星を読む神が星明かりを縒って作った弦。引いた者の力はその瞬間のまま固まり、張り詰めた弦が最初の矢を弾く。","h":"1x2rv43"},
"PI-B1": {"n":"ドルマクの心火","f":"火冠山脈の下、巨人の冷めぬ心火をひと掬い汲んできた。持つ者の力はその日からその火の強さで決まり、防いだ刃先にも炎が返る。","h":"1kb57p5"},
"PI-B2": {"n":"ソルグリムの腱","f":"鉄骨山脈に露わな鉱脈、眠る巨人の腱一筋を撚って体に巻いた。切れたことがなく、熱を帯びれば触れるもの皆に火が付く。","h":"16ryigv"},
"PI-B3": {"n":"ズラクの雷瓶","f":"雷の大精霊が囚われ、逃げ出した瓶。残った雷が不揃いに指先で弾け、瓶を割ろうとした者はその火花に焼かれる。","h":"j3yj5d"},
"PI-G1": {"n":"カルノの決闘籠手","f":"灰鬣のカルノが百度目の決闘で脱ぎ捨てた籠手。はめた拳はどんな呪いにも縮まず、打たれた所は戦う間に癒える。","h":"18d4l67"},
"PI-G2": {"n":"ドリエンの種","f":"森の大精霊が抱いた最初の種。植えた体に古木の寿命が宿る。斬っても同じ背丈で育ち直し、伸びた枝は息の根を狙う。","h":"xwe5wa"},
"PI-G3": {"n":"マレンシアの鱗","f":"水の竜が盟約の日に落とした鱗一枚。持つ者の姿をその日のまま守り、鱗の光を見た敵は魂を奪われる。","h":"1a40guc"},
"PN-A1-C1": {"n":"幼き吸血鬼","f":"ノクタール貴族の宴で杯の代わりに誓約書を受け取った客だった。今では牙の血が乾かぬ代わりに、傷も癒えない。","k":"吸血鬼","h":"ajjoe"},
"PN-A1-C2": {"n":"モルク峡谷のシェイド","f":"モルク峡谷の底から這い上がった主なき影。光を浴びると薄れて見えなくなるだけで、消えたことはない。","k":"シェイド","h":"pl2qj8"},
"PN-A1-C3": {"n":"契約の屍巨人","f":"契約に記された力の分だけ振るうよう縫い合わされた巨人。何人分かは契約書の裏に書いてある。","k":"屍巨人","h":"1bkny2w"},
"PN-A1-E": {"n":"帳の取引人","f":"深淵の帳に何かを置いてきた案山子。何を置いてきたのかは本人も覚えていない。傷が癒えないのはそのためだ。","k":"案山子","h":"1h6oo5c"},
"PN-A1-R": {"n":"影の契約執行者","f":"アズラの契約書の写しを懐に抱く。契約を破った者の息を、きっかりひとつだけ残す。","k":"大鴉","h":"popbv6"},
"PN-A1-U1": {"n":"血誓の剣士","f":"剣に己の血を吸わせて誓い、死してなお立ち上がった。誓いの代価を払い終えるまで、墓は彼を受け入れない。","k":"死の騎士","h":"1dbjjqw"},
"PN-A1-U2": {"n":"モルカスの徴税人","f":"死んだ日も帳簿を離さず、そのまま亡霊になった。沈黙の君主に納める分は、今も一銭たりともまけない。","k":"亡霊","h":"1v2svwy"},
"PN-A2-C1": {"n":"暁城の小聖像","f":"暁城の道端の壁龕ごとに置かれた小さな聖像。ソランテの光に洗われ帰る場所を失った者は、この姿となってエラドを守る。","k":"聖像","h":"1n68q68"},
"PN-A2-C2": {"n":"エラドのオファニム","f":"目の埋まった金の車輪が二つ、噛み合って回る。エラドの城壁の一区画を任されて以来、その場から一寸も転がったことがない。","k":"オファニム","h":"15h6073"},
"PN-A2-C3": {"n":"黄昏障壁のペガサス","f":"空白の地に面した黄昏の障壁の上を飛ぶ。障壁の向こうから何が来ても、翼をたたまない。","k":"ペガサス","h":"1ojiggi"},
"PN-A2-E": {"n":"黄昏障壁の誓約者","f":"灰色の牢獄を封じた古の聖光騎士団、最後の誓約者。あの日の誓いを、まだ解いていない。","k":"誓魂","h":"123phjx"},
"PN-A2-R": {"n":"暁光の盾獅子","f":"日の昇る方へだけたてがみを立てる。そばに立つ者を狙った最初の刃は、そのたてがみの暁の光に滑る。","k":"暁獅子","h":"cfv5ju"},
"PN-A2-U1": {"n":"誓いを刻む騎士","f":"騎士はとうに倒れ、鎧の内に刻んだ誓いだけが残ってその鎧をまとい立ち上がった。誓いが守られる限り、空の鎧は折れない。","k":"誓魂","h":"b2xyfg"},
"PN-A2-U2": {"n":"ソランテの聖歌隊","f":"夜明けごとに六枚翼の母へ歌うヒバリの群れ。歌が終わるまで誰も倒れないと信じ、なかなか歌を終えない。","k":"ヒバリ","h":"ponnk5"},
"PN-A3-C1": {"n":"星座の猟犬","f":"夜空を駆ける猟犬の星座。一度通った道は星明かりとなって残り、忘れられない。","k":"星座","h":"1pjs5ey"},
"PN-A3-C3": {"n":"長弓グリフィン騎士","f":"嵐の塔弓士会で騎士に叙されたグリフィン。長弓を引く手はないが、ひと羽ばたきで風の矢が長弓の射程ほど飛ぶ。","k":"グリフィン","h":"oz3a3r"},
"PN-A3-E": {"n":"イサクの最初の弟子","f":"星の文字を解読したイサクに初めて弓を習った雪豹。師が星の間へ去った後も、同じ星を狙う。","k":"雪豹","h":"1f7z5z3"},
"PN-A3-R": {"n":"星明かりの弓士長","f":"千の目が嵌まったローブの裾を授かった。そばに立つ射手の矢は、その目が照らした鎧の隙間へひとりでに曲がる。","k":"孔雀","h":"1tg6ep4"},
"PN-A3-U1": {"n":"星文字のフクロウ","f":"羽根ごとに星の文字が刻まれたフクロウ。羽ばたきで送った文字はどんな風にも散らない。","k":"星フクロウ","h":"ym5xpc"},
"PN-A3-U2": {"n":"天の揺籃グリフィン","f":"針の塔の頂の関門前に巣を構えた。風の竜シレルが悪戯を仕掛けても、関門も巣も揺るがない。","k":"グリフィン","h":"wazwzv"},
"PN-B1-C1": {"n":"幼サラマンダー","f":"火薬庫の焚き口で孵った幼い蜥蜴。フォルタンの装填兵は火種が足りないと、その尾に火縄を当てて火を借りる。","k":"サラマンダー","h":"whfcd6"},
"PN-B1-C3": {"n":"砲撃ミイデラ","f":"尻から煮えた汁を放つ火冠山脈の甲虫。フォルタンの砲台より装填が速いという噂を、砲手たちは聞こえないふりをする。","k":"爆弾虫","h":"1n01xyl"},
"PN-B1-E": {"n":"脈打つ心火片","f":"ドルマクの心火から剥がれて、今も脈打つ欠片。タラクスの脈動が速まるほど共に速まるが、フォルタンはそれが良いことかを問わない。","k":"心火の破片","h":"xndvj4"},
"PN-B1-R": {"n":"硝煙の火鷹","f":"硝煙が最も濃い時にだけ急降下する火鷹。その羽ばたきが煙の上を舞う間は、フォルタンの砲手も手が速くなる。","k":"火鷹","h":"1ner02d"},
"PN-B1-U1": {"n":"溶鉱炉の炉霊","f":"フォルタンの火薬庫脇の溶鉱炉に宿る炎の精霊。火薬庫には火種ひとつ入れないくせに、自分はめったに消えない。","k":"炉の精","h":"1gfc6w4"},
"PN-B1-U2": {"n":"ドルマクの火蜘蛛","f":"火冠山脈の下、ドルマクの胸骨の間に溶けた石で糸を張る蜘蛛。かかったものは抜け出す前に固まる。","k":"火蜘蛛","h":"1se4nyx"},
"PN-B2-C1": {"n":"リベット鋏ガニ","f":"鉄骨山脈の錆水の溜まりでリベットを拾い、甲羅に打ち込むカニ。どこを叩いても同じ音がする。","k":"鉄甲ガニ","h":"fugwts"},
"PN-B2-C2": {"n":"蒸気掘りモグラ","f":"鉄の鉱脈を掘り食らって生きるモグラ。鼻息が蒸気のように熱く、ドゥルクハイムの坑夫は彼の通った穴で凍えた手を温める。","k":"鋼のモグラ","h":"1l4zmzt"},
"PN-B2-C3": {"n":"鉄骨槌の巨像","f":"鉄骨山脈の鉱脈から掘った鉄だけで作った巨像。両腕が丸ごと槌なので、防げばひとりでに打ち下ろす。","k":"巨像","h":"y0ruqn"},
"PN-B2-E": {"n":"フェロスを見たゴーレム","f":"鉱脈の深くで金属の竜フェロスと出会い、戻ってきたゴーレム。以来、その体は鏡のように映し返す。","k":"ゴーレム","h":"mzgtye"},
"PN-B2-R": {"n":"ソルグリムの盾霊","f":"眠るソルグリムが何かを防ごうと掲げた腕の記憶が、鉄の上に結んだ。それの立つ列では、盾が少しずつ硬くなる。","k":"盾の精霊","h":"1918usv"},
"PN-B2-U1": {"n":"ドゥルクハイム盾工","f":"自分の尾で打った盾しか持たない。盾に残る傷は、すべて彼が守り抜いた日の数だ。","k":"鉄尾ビーバー","h":"1sdf20i"},
"PN-B2-U2": {"n":"鉱脈甲虫","f":"ソルグリムの腱が露わな鉱脈を齧るうち、殻が鉱石になった甲虫。その殻は溶けも曲がりもせず、打った側の手首が先に泣く。","k":"鉱石甲虫","h":"1ob0tfe"},
"PN-B3-C1": {"n":"雷獣の子","f":"雷の落ちた場所で拾ってきた雷獣の子。転んでも放電しないので、見習いたちが抱っこを取り合う。","k":"雷獣","h":"1gby8gq"},
"PN-B3-C2": {"n":"暴走蓄電器","f":"限界まで充電した蓄電器に脚をつけた。これ以上入れれば爆ぜる。直すこともできない。","k":"蓄電器","h":"l78c75"},
"PN-B3-C3": {"n":"絶縁甲冑機関","f":"ゴムとガラスを幾重にも巻いたヴォルタリウムの歩く機関。雷も刃も同じ厚みで止まる。","k":"雷電機関","h":"zqfkz7"},
"PN-B3-E": {"n":"ケラウン神経増幅器","f":"眠る巨人の神経の一筋に歩く装置を吊るした。雷が一度通れば、並ぶものすべてが震える。","k":"蓄電器","h":"ywsph3"},
"PN-B3-R": {"n":"瓶の雷術士","f":"ズラクが逃げた後、残った空き瓶に小さな雷を詰め直して回る。瓶が割れるたび味方の魔法が大きくなる。","k":"ジン","h":"1tlq0ad"},
"PN-B3-U1": {"n":"避雷塔の磁霊","f":"避雷塔の頂で無数の霹靂を受けた鉄が精霊になった。近くの釘や鍵が引き寄せられ、味方の魔法も少し強くそちらへ曲がる。","k":"磁石の精霊","h":"ox8k6p"},
"PN-B3-U2": {"n":"雷鳴高原の雷鳥","f":"ケラウンの神経が走る場所を選んで降りる雷鳥。止まった岩ごとに雷が落ちるので、測量士は後を追って杭を打つ。","k":"雷鳥","h":"ocj7zg"},
"PN-G1-C1": {"n":"岩牙の末っ子","f":"族でいちばん幼いが、牙は兄たちと同じ。誰が何と言おうと、牙は縮まない。","k":"剣歯虎","h":"hwf6rq"},
"PN-G1-C3": {"n":"大岩の巨躯","f":"数十の大岩がひと塊になった岩の精霊。ガルウン大野営地で一番大きいのがオークでなくなった日、オークたちは少し寂しがった。","k":"岩の精霊","h":"ezjgn9"},
"PN-G1-E": {"n":"王座峰のマンモス","f":"ゴルヴァスの背の雪深い峠に棲むマンモス。オークを乗せて王座峰を下ると、雪崩が後に続く。","k":"マンモス","h":"1q1qdh6"},
"PN-G1-R": {"n":"カルノを追う者","f":"灰鬣のカルノが通った決闘場を巡り、そこの勝者に決闘を挑む。","k":"ビッグホーン","h":"18hkytl"},
"PN-G1-U2": {"n":"熊皮の狂戦士","f":"素手で仕留めた熊の皮をかぶって戦ううち、ある日その皮が脱げなくなった。以来、何ものもその勢いを挫けない。","k":"ワーベア","h":"19ir590"},
"PN-G2-C1": {"n":"苔むした苗木","f":"切っても翌日には同じ背丈で立っている。トロールたちはそれを意地と呼ぶ。","k":"トレント","h":"1jrp0h9"},
"PN-G2-C2": {"n":"茨の蔓鬼","f":"錆の沼のほとりを這い回る茨。抜こうとすれば、根がひと握りずつ深くなる。","k":"蔓の怪物","h":"4euc13"},
"PN-G2-C3": {"n":"沼辺のヒドラ","f":"錆水川が届く沼辺に住む多頭の蛇。首を一つ斬れば、錆水の匂いがする首が二つ生える。","k":"沼ヒドラ","h":"slk0ud"},
"PN-G2-E": {"n":"太古林の苔角鹿","f":"世界最初の森から下りてきた鹿。ヴェルダンの角の陰で千年眠り、眠る間に角に森が育った。","k":"角鹿","h":"1rpjbhg"},
"PN-G2-R": {"n":"ドリエンの苔巨人","f":"森の大精霊ドリエンが通った跡から立ち上がった。苔の下に棘が、棘の下に森の記憶がある。","k":"苔の巨人","h":"1615zzg"},
"PN-G2-U1": {"n":"巻きひげピクシー","f":"体に巻いた巻きひげが傷をすぐに縛る。棘の矢を射る手だけは蔓から出してある。","k":"ピクシー","h":"1o1y6dt"},
"PN-G2-U2": {"n":"菌糸の根守り","f":"巨樹の都の根の間に菌糸を伸ばしたキノコ族。シルヴァニエルの根が互いに便りを交わせるのは彼らのおかげだ。","k":"キノコ族","h":"1mdgio"},
"PN-G3-C1": {"n":"生ける水鏡","f":"セレネアの潟湖で最も静かな水が立ち上がり、鏡となった。映る姿は傷ついても減らない。","k":"水鏡","h":"ik57g0"},
"PN-G3-C3": {"n":"海溝の歌鯨","f":"タラクス海溝でマレンシアに捧げる歌だけを歌う鯨。一曲歌い終えるのに一季節かかる。","k":"クジラ","h":"7oy389"},
"PN-G3-E": {"n":"ウルボア鱗騎士","f":"深海の大蛇ウルボアが脱いだ鱗で鎧を作った。どんな槍もその鱗を薄くできなかった。","k":"ナーガ","h":"uexsbv"},
"PN-G3-R": {"n":"ネリアの水器巫女","f":"水の大精霊ネリアを宿す器を捧げ持つ。器から溢れる深海の歌が傍らの者を包み、刃先を鈍らせる。","k":"ネレイス","h":"1gega5l"},
"PN-G3-U2": {"n":"タラクスのアンコウ","f":"海溝の底で巨人の鼓動に合わせて灯を瞬かせるアンコウ。鼓動が続く限り、その灯も消えない。","k":"アンコウ","h":"87hckn"},
"PS-A1-1": {"n":"魂の搾取","t":"相手ユニットのうち攻撃が最も高いユニット2体の攻撃−3(0まで)。削った分の合計だけ味方の先頭ユニットの攻撃+。","f":"ノクタールの契約書には、いつも一行多い。奪ったものは奪った者のものになる。","b":"{敵攻撃最高2体} ⚔−3|{味方前1体} ⚔+ 削った分","h":"e57vwh"},
"PS-A1-2": {"n":"疫病の枷","t":"相手ユニットのうち攻撃が最も高いユニット1体の攻撃−2。そのユニットに[疫病 2]。","f":"錆びた枷が縛るのは足首ではなく息だ。鎖が解けても、咳は隣の者へ移っていく。","b":"{敵攻撃最高1体} ⚔−2 [疫病 2]","h":"2nriyh"},
"PS-A2-1": {"n":"聖痕","t":"味方の先頭ユニット2体に[加護 1]。このターン味方ユニットが失った体力分の[暁光]が溜まる。","f":"天族の流した血は地に染みない。傷ごとに光が溜まり、その光は夜明けとともに一度に溢れ出す。","b":"{味方前2体} [加護 1]|味方が失った♥ → [暁光]","h":"ida4y4"},
"PS-A2-2": {"n":"秩序の光","t":"相手ユニット全体の攻撃が、その中で最も低い攻撃と同じになる。","f":"ソランテの秩序の下では、何ものも溢れず欠けない。暴れていた刃も、その光の下では等しく伏す。","b":"{敵全体} ⚔ = 敵の最も低い⚔","h":"u2t3sb"},
"PS-A3-1": {"n":"循環","t":"相手先頭ユニットの攻撃が防御へ、防御が体力へ、体力が攻撃へ移る。","f":"星は巡り、巡った星は元の場所に戻らない。イサクが初めて読んだ文字は、そのひと巡りだった。","b":"{敵前1体} 循環 ⚔→⛨→♥→⚔","h":"jam1d1"},
"PS-A3-2": {"n":"星の模写","t":"味方先頭ユニット2体の攻撃・防御・体力のうち、相手ユニットで攻撃が最も高い1体より低いものはその値になる。","f":"ハイエルフは見たものを星の文字で記し、記したものを己の身に移す。","b":"{味方前2体} ⚔⛨♥ 低いもの = {敵攻撃最高1体}","h":"g0xfdk"},
"PS-B1-1": {"n":"逆火","t":"敵ユニットのうち攻撃が最も高いユニット1体が、自身の攻撃分の物理ダメージを受ける(自身の防御分軽減)。","f":"フォルタンの火薬はいつも少しずつ溢れる。溢れた火は、最も大きく振りかぶった者の手で爆ぜる。","b":"{敵の攻撃最高1体} 自身の⚔分の物理ダメージ","h":"xvi3mc"},
"PS-B1-2": {"n":"燃える覚悟","t":"味方ユニット2体の攻撃+3。それらの攻撃はこのターン減らない。","f":"導火線に火がつけば戻せない。ゴブリンはそれを覚悟と呼ぶ。","b":"{味方2体} ⚔+3 · このターン⚔減らない","h":"1a4v7tc"},
"PS-B2-1": {"n":"鋼の誓い","t":"味方の先頭ユニット2体の防御+1、体力+1。その2体の防御・体力はこのターン減らない(ダメージを除く)。","f":"ドゥルクハイム工房の誓いは短い。「錆びない」。","b":"{味方前2体} ⛨+1 ♥+1|{味方前2体} このターン⛨ ♥減らない","h":"8haqog"},
"PS-B2-2": {"n":"焼き入れ","t":"味方の先頭ユニットの体力が攻撃に、防御が体力に、攻撃が防御に移る。","f":"灼けた鉄を打って水に浸せば、柔い所は硬くなり、硬い所は刃となる。ゴーレムもそうだ。","b":"{味方前1体} 循環 ⚔→⛨→♥→⚔","h":"1dve9h3"},
"PS-B3-1": {"n":"増幅回路","t":"味方の先頭ユニット2体にこのターン[増幅 1]。","f":"ヴォルタリウムのノームが兵二人の背に銅の回路を挿した。空の雷が二人を経て一段太く落ちる。","b":"{味方前2体} [増幅 1]","h":"1ovqzqk"},
"PS-B3-2": {"n":"電極交換","t":"攻撃が最も低い味方ユニット1体と、攻撃が最も高い相手ユニット1体の攻撃を入れ替える。","f":"陽極と陰極を入れ替えれば、流れる力は逆に流れる。ノームはその向きを決めるだけでいい。","b":"{味方攻撃最小1体} ⚔ ↔ {敵攻撃最大1体} ⚔","h":"rkr3eo"},
"PS-G1-1": {"n":"勝鬨","t":"戦闘終了時、生き残った味方ユニット数だけ相手のライフ−。","f":"戦いが終わり、立っている者が共に吠える。その声に、敵陣が一歩ずつ崩れる。","b":"{敵ライフ} −(戦闘終了時の生存味方数)","h":"7vo6vt"},
"PS-G1-2": {"n":"群れの怒り","t":"味方ユニット全体の攻撃が、味方で最も高い攻撃と同じになる。","f":"頭目が吠えれば、群れ全体が頭目ほど猛々しくなる。","b":"{味方全体} ⚔ = 味方の最高⚔","h":"3b5jx4"},
"PS-G2-1": {"n":"年輪","t":"味方ユニット1体の体力+2、防御+1。そのユニットの体力はこのターン減らない(ダメージを除く)。","f":"古木は一年耐えるごとに輪を一つまとう。まとった輪は剥がれない。","b":"{味方1体} ♥+2 ⛨+1|このターン ♥ 減らない","h":"48yocc"},
"PS-G2-2": {"n":"根を下ろす","t":"味方先頭ユニット2体の攻撃をすべて防御に移す(攻撃0、防御+移した値)。","f":"トロールが戦いをやめ、地に足を埋める。その場で木となって耐える。","b":"{味方前2体} ⚔をすべて⛨へ","h":"l8d2ww"},
"PS-G3-1": {"n":"水の鏡","t":"敵ユニットのうち攻撃が体力より高いユニット全体の攻撃と体力を入れ替える。","f":"ネリアの水に映る姿は逆さに立つ。刃が体となり、体が刃となる。","b":"{敵全体} ⚔ > ♥ なら ⚔ ↔ ♥","h":"1owiq2a"},
"PS-G3-2": {"n":"引き潮","t":"敵ユニット全体の攻撃−2。このターン、敵ユニット全体の攻撃はこれ以上上がらない。","f":"水が引けば、波に乗った者たちの勢いも共に引く。次の潮時まで再び満ちることはない。","b":"{敵全体} ⚔−2・このターン⚔上がらない","h":"1xixzp"},
"RA1-1": {"n":"最後の契約","t":"戦場のユニットを双方すべて破壊する。","f":"モルカスと結ぶ最後の取引。代価は戦場のすべての命で、天秤はぴたりと水平になる。","b":"{双方全体} 破壊","h":"10vxcq0"},
"RA2-1": {"n":"審判の日","t":"味方の先頭ユニットに[障壁]。双方のユニット全体の体力−6。[装填 2]","f":"空が真昼より明るくなる日、光は敵味方を選ばない。ただ先頭に立つ者だけが翼の下に残る。","b":"{味方前1体} [障壁]|{双方全体} ♥−6","h":"t5umre"},
"RA3-1": {"n":"嵐の目","t":"相手ユニット全体はこのターン攻撃も反撃もしない。味方ユニット全体の体力−2。[装填 2]","f":"嵐の只中の静けさが戦場を呑む。刃も呪文も止まり、その代償に呼んだ者たちの息が削られる。","b":"{敵全体} 攻撃・反撃封じ|{味方全体} ♥−2","h":"1razkh5"},
"RB1-1": {"n":"火薬樽敷設","t":"この魔法の位置と味方の空き枠ごとに、火のついた火薬樽(0/0/2)を置く。火薬樽は置かれたターンに攻撃・反撃せず、魔法や攻撃で壊れることがある(壊れると不発)。次のターンの最初の攻撃前に爆発し、同じ枠番号の敵ユニットに[火傷 3]。","f":"フォルタンが崩れるたび、ゴブリンは空の塹壕に火薬樽を転がし込んだ。守り手が少ないほど、爆音は大きかった。","b":"{味方の空き枠} 火薬樽|次ターン同じ枠の敵に火傷3","h":"g2bwot"},
"RB2-1": {"n":"工房自爆命令","t":"味方ユニットをすべて破壊し、相手ユニット全体の体力−7。[装填 2]","f":"工房長はついにその命令を下した。ゴーレムたちの心臓が一斉に弾け、坑道一本が丸ごと崩れた。","b":"{味方全体} 破壊|{敵全体} ♥−7","h":"wc04q2"},
"RB3-1": {"n":"ケラウン大放電","t":"相手ユニット全体の体力−2 −2C×3。味方ユニット全体の体力−3。[装填 2]","f":"ケラウンの神経に溜まった雷を一度に引き抜いた。眠る巨人が身震いし、高原全体が白く光った。","b":"{敵全体} ♥−2 −2C×3|{味方全体} ♥−3","h":"c9p9i"},
"RG1-1": {"n":"頭目狩り","t":"攻撃が最も高い相手ユニット3体を破壊する。味方ユニットもすべて破壊する。","f":"頭目の首を狙い、群れ全体が身を投げる。狩りが終われば、草原には風の音だけが残る。","b":"{敵 攻撃上位3体} 破壊|{味方全体} 破壊","h":"1w61ymu"},
"RG2-1": {"n":"森の静寂","t":"双方のユニット全体の攻撃が0になる。敵ユニット全体に体力−3。[装填 3]","f":"森全体が息を潜める。鳥も風も剣も止まった静けさの中、棘だけがゆっくりと伸びる。","b":"{双方全体} ⚔=0|{敵全体} ♥−3","h":"1rrwhbw"},
"RG3-1": {"n":"大津波","t":"両陣営のユニット全体の体力−4。その後、味方先頭ユニットにこのターン[治癒 1]。","f":"タラクスの鼓動が一度大きく打つ。海はすべてを呑み込み、人魚にだけ息を返す。","b":"{両陣営全体} ♥−4|{味方前1体} [治癒 1]","h":"900ycz"},
"RS-A1-1": {"n":"血の槍","t":"[生贄 2] 相手ユニットのうち攻撃が最も高いユニット1体の体力−6。","f":"己の血を固めて鍛えた槍。ノクタールの契約者は最も危険な敵から貫く。","b":"{生贄} ライフ 2|{敵攻撃最高1体} ♥−6","h":"dupzsj"},
"RS-A1-2": {"n":"吸血の帳","t":"相手の先頭ユニット2体の攻撃−4(0まで)。削った分の合計だけ味方の先頭ユニットの攻撃+、そのユニットの体力+2。","f":"モルク峡谷の影は近づく者の力を吸い、門番に与える。代価はいつも相手が払う。","b":"{敵前2体} ⚔−4|{味方前1体} ⚔ + 削った分、♥+2","h":"1tzgdxs"},
"RS-A1-3": {"n":"精神支配","t":"[呪い]を受けているかレベル3以下の相手ユニットのうち、攻撃が最も高いユニット1体をこのターン自分の戦場の最後尾に連れてきて味方として戦わせる。生き残れば戦闘終了時に相手の戦場の最後尾へ戻る。","f":"朔の囁きは怯えた心から入り込む。昨日の仲間に剣を向けた兵は、日が暮れてようやく己の名を思い出す。","b":"{敵 [呪い]またはL3以下 · ⚔最高1体} このターン味方|生きれば相手の最後尾へ","h":"15q4ell"},
"RS-A2-1": {"n":"光の審判","t":"味方の先頭ユニット2体の防御がこのターン0になる。削られた防御の合計分、相手の先頭ユニットの体力を削り、倒して残った分は次のユニットへ。","f":"暁城の騎士たちは審判の日に盾を下ろす。盾に集まっていた光が一筋の槍となり、敵の隊列を貫く。","b":"{味方前2体} ⛨ → 0|削られた⛨の合計 → {敵先頭から} ♥− (残りは次へ)","h":"dvvj6u"},
"RS-A2-2": {"n":"応報の光","t":"味方ユニット全体に[加護 1]。戦闘終了時、このターン味方が[障壁] · [加護]で防いだダメージ分、体力が最も高い相手ユニットの体力を削る。","f":"天族の翼に阻まれた刃は消えない。光として集まり、戦いが終わる瞬間、その刃を振るった者へ返る。","b":"{味方全体} [加護 1]|防いだダメージ → {敵 ♥最高1体} ♥−","h":"1kvdg3k"},
"RS-A2-3": {"n":"光の結界","t":"味方の先頭ユニットに[障壁]。相手の先頭ユニットの攻撃−3、体力−1。","f":"ソランテに誓った者の前に光の円が描かれる。その円を越える刃は光に目が眩み、力を失う。","b":"{味方前1体} [障壁]|{敵前1体} ⚔−3 ♥−1","h":"1vqmms4"},
"RS-A3-1": {"n":"かまいたち","t":"相手ランダムユニットに体力−2を2回。","f":"嵐の塔の見習い射手が最初に覚える風術。刃のように研いだ風は、矢より先に鎧の隙間を裂く。","b":"{敵ランダム} ♥−2 ×2回","h":"1hfb5g2"},
"RS-A3-2": {"n":"逆風の障壁","t":"相手先頭ユニット3体の攻撃−3、体力−1。","f":"針の塔を登ろうとする者は、まず逆さに吹く風に出会う。突き出した刃は自分の顔へ返ってくる。","b":"{敵前3体} ⚔−3 ♥−1","h":"1elfb91"},
"RS-A3-3": {"n":"旋風の刃","t":"相手ランダムユニットに体力−2を3回。相手ユニット全体の攻撃−1。","f":"ベルミルの針の頂から降りてきた旋風。中の風の刃は数えきれず、巻き込まれた者は立ってもいられない。","b":"{敵ランダム} ♥−2 ×3回|{敵全体} ⚔−1","h":"1h6sk4s"},
"RS-B1-1": {"n":"火の海","t":"敵ユニット全体の体力−3。敵の先頭ユニット2体はさらに体力−3。[装填 1]","f":"フォルタン砲兵団は計算しない。火薬をあるだけ撃ち込み、残りは翌日また詰める。","b":"{敵全体} ♥−3|{敵前2体} さらに♥−3","h":"1eibafa"},
"RS-B1-2": {"n":"埋設地雷","t":"敵の先頭ユニット2体の体力−2。","f":"ノコギリ峠へ登る道には、ゴブリンだけが知る石がある。踏んではならない石だ。","b":"{敵前2体} ♥−2","h":"fs0sn2"},
"RS-B1-3": {"n":"火種弾幕","t":"敵ユニット全体の体力−1 −1C。そのうち攻撃が最も高いユニット1体はさらに体力−2。","f":"ドルマクの心火をひと握りずつ詰めた弾。散った火種は、最も大きく刃を掲げた者に集まる。","b":"{敵全体} ♥−1 −1C|{敵の攻撃最高1体} さらに♥−2","h":"1smgv2q"},
"RS-B2-1": {"n":"粉砕ハンマー","t":"相手の先頭ユニット2体の防御−2、体力−2。","f":"ドゥルクハイムの職人は鎧を作れるから、壊し方も知っている。継ぎ目一つを打てばいい。","b":"{敵前2体} ⛨−2 ♥−2","h":"czr86f"},
"RS-B2-2": {"n":"ゴーレム方陣","t":"味方全体の防御+1、体力+2、[加護 2]、[呪い免疫]。","f":"ゴーレムが肩を並べれば鉄骨山脈の一角となる。呪文ごときが割り込む隙はない。","b":"{味方全体} ⛨+1 ♥+2|{味方全体} [加護 2] [呪い免疫]","h":"1c79018"},
"RS-B2-3": {"n":"リベットの嵐","t":"味方全体の防御+1、体力+1。相手ユニット全体の防御−1、体力−2。","f":"工房のリベット機が一斉にひっくり返った。行き場を探すリベットは味方の鎧に収まり、敵の鎧は貫いていく。","b":"{味方全体} ⛨+1 ♥+1|{敵全体} ⛨−1 ♥−2","h":"foifh1"},
"RS-B2-4": {"n":"鉄壁進撃","t":"味方ユニット全体の防御+1。その後、味方ユニット全体の防御の合計分、味方の先頭ユニットから攻撃が上がる — 一体後ろへ行くごとに1ずつ減る。","f":"盾を合わせたドゥルクハイムの陣は退かない。前へ傾く瞬間、後ろの皆の重みが先頭の盾を槌に変える。","b":"{味方全体} ⛨+1|{味方全体} ⚔ + ⛨合計 (先頭から−1ずつ)","h":"1m3qlx3"},
"RS-B3-1": {"n":"蓄電解放","t":"相手の待機列の先頭から順に体力−2 → −2 → −2。","f":"ヴォルタリウムの蓄電瓶三つを一列に繋いだ。雷は衰えず次の瓶へ渡る。","b":"{敵先頭から} 順に ♥−2→−2→−2","h":"18pxdu4"},
"RS-B3-2": {"n":"感電の罠","t":"相手ユニット全体の攻撃−2、体力−1 −1C×2。","f":"ノームの工房の敷居には銅線が敷かれている。越えた者の刃はひとりでに手から落ちる。","b":"{敵全体} ⚔−2|{敵全体} ♥−1 −1C×2","h":"uvi99t"},
"RS-B3-3": {"n":"充電完了","t":"このターン、味方ユニットのコイン:+コインはすべて表、−コインはすべて裏。相手の先頭ユニット2体の体力−2 −1C。","f":"目盛りが振り切れた。こんな日のノームの装置は一度も外れたことがない。","b":"{味方} コインすべて有利|{敵前2体} ♥−2 −1C","h":"zvxs3j"},
"RS-G1-1": {"n":"狼の奇襲","t":"相手の先頭ユニットの体力−2。味方ユニット2体の攻撃+1、[破甲]。","f":"吠える草原の狼がまず噛みつき、その背のオークが裂けた鎧をさらに引き裂く。","b":"{敵前1体} ♥−2|{味方2体} ⚔+1 [破甲]","h":"18d27va"},
"RS-G1-2": {"n":"血の誓い","t":"味方ユニットそれぞれを血(🩸)で結ぶ。結ばれたユニットが倒れると、持つ血はすべてすぐ後ろの味方へ移る。戦闘終了時、他者の血を宿して生き残ったユニットは、次のターンの準備時、その血の主たちが倒れた時の攻撃だけ攻撃が上がる(そのターンのみ)。","f":"ガルウンのオークは掌を裂いて血を交わす。先に倒れた者の怒りは、後ろに立つ兄弟の拳で再び目覚める。","b":"{味方全体} 🩸結束|倒れると🩸→後ろ|次ターン⚔+(倒れた⚔)","h":"rhsn2y"},
"RS-G1-3": {"n":"大地割り","t":"相手の先頭ユニットの防御−1。相手ユニット全体に物理ダメージ3。味方全体の攻撃+1。","f":"拳ひとつで大地を割ったというオークの歌は誇張ではない。ゴルヴァスがその拳を許しただけだ。","b":"{敵前1体} ⛨−1|{敵全体} 物理ダメージ3|{味方全体} ⚔+1","h":"1kd9qka"},
"RS-G2-1": {"n":"根の奇襲","t":"敵ユニット3体に体力−2。味方ユニット2体の体力+2。","f":"地下を這った根は敵の背後から突き出る。吸い上げたものは、そのまま味方の樹液となる。","b":"{敵3体} ♥−2|{味方2体} ♥+2","h":"x82oq3"},
"RS-G2-2": {"n":"茨の藪","t":"味方全体の体力+3、[棘 2]。","f":"シルヴァニエルの外の森道は、一夜で藪に閉ざされる。斬って入った者は、斬った分だけ刺される。","b":"{味方全体} ♥+3 [棘 2]","h":"1mbkyes"},
"RS-G2-3": {"n":"しぶとい苔","t":"味方全体の体力+2、[不屈]。","f":"トロールの体を覆う苔は、主が倒れるのを許さない。舞う胞子は敵の息を詰まらせる。","b":"{味方全体} ♥+2 [不屈]","h":"1yx1wyd"},
"RS-G3-1": {"n":"銛の潮流","t":"敵の先頭ユニットの[障壁]・[棘]・[呪い免疫]・[守護]が消え、体力−3。味方先頭ユニットにこのターン[治癒 1]。","f":"潮に乗って飛んだ銛は、盾も祝福も洗い流して突き刺さる。セレネアの狩人は二度投げない。","b":"{敵前1体} 解除・♥−3|{味方前1体} [治癒 1]","h":"197qc9h"},
"RS-G3-2": {"n":"泡沫の帳","t":"味方先頭ユニットに[障壁]、このターン[浄化]。味方全体の体力+1。","f":"泉の巫女団が歌う泡の歌。最初の刃は泡に滑り、傷は水滴に閉じる。","b":"{味方前1体} [障壁]・[浄化]|{味方全体} ♥+1","h":"k63n8"},
"RS-G3-3": {"n":"満ち潮の歌","t":"敵ユニット全体のコインが裏になる(すでに決まったコインはそのまま)。敵ユニット全体の体力−2。味方全体の体力+1。味方先頭ユニットにこのターン[治癒 1]。","f":"マレンシアの海が満ちる刻に合わせて歌う歌。押し寄せた水は敵の運をさらい、味方の足を濡らす。","b":"{敵全体} コイン裏・♥−2|{味方全体} ♥+1|{味方前1体} [治癒 1]","h":"12z4rrw"},
"S2-1": {"n":"光の聖印","f":"ソランテの聖印。毎ターン、最初に飛んでくる刃を少し鈍らせる。","h":"1s3ulxc"},
"S3-1": {"n":"契約の印章","f":"モルカスと結んだ契約の印章。代価を先に払ったゆえ、自分より大きな者の剣は影のようにそれていく。","h":"x11xwr"},
"S4-1": {"n":"ソランテの聖遺物","f":"太陽神の聖遺物。神が顔を背けた日には、何も防げない。","h":"1ydhivb"},
"SA1-01": {"n":"深淵の呼び声","t":"[生贄 2] 自分の焼却場のユニットのうち、レベルがこのターン捧げた生贄以下のユニットをひとつ(レベルが最も高いもの)このマスに蘇らせる。蘇ったユニットは戦場に残る。","f":"モルカスの天秤は死者も量る。生者が血を十分に載せれば、向かいの皿で誰かが立ち上がる。","b":"{生贄} ライフ 2|{自分} 焼却場のユニット1体を蘇生 (レベル ≤ 捧げた生贄)","h":"xyfz8a"},
"SA1-02": {"n":"影の掌握","t":"相手ユニットのうち、レベルが(このターン捧げた生贄+1)以下のユニットをひとつ(レベルが最も高いもの)奪い、自分の戦場の最後尾に置く。このターン自分のユニットとして戦い、戦闘が終わると散る(元の持ち主の焼却場へ)。","f":"足元の影が手となって敵を掴む。血を多く捧げるほど、その手はより大きなものを引き寄せる。","b":"{敵1体} 奪う (レベル ≤ 捧げた生贄+1) · このターン","h":"6tn8wm"},
"SA1-04": {"n":"鏡の幻影","t":"[生贄 2] 相手ユニットのうち攻撃が最も高いユニット1体の幻影をこのマスに呼ぶ。幻影はそのユニットと同じカード(アイテムなし)としてこのターン自分の側で戦い、戦闘が終わると消える。","f":"モルカスの鏡に映った者は己の影と戦う。影は本物の力をそのまま借りるが、本物の鎧は借りられない。","b":"{生贄} ライフ 2|{敵攻撃最高1体}の幻影を自分の側に · このターン","h":"p2gzr"},
"SA1-06": {"n":"血の生贄","t":"味方ユニットそれぞれの体力−1。削れた体力の合計の3倍だけ相手の先頭ユニットの体力を削る。倒して余った分は次のユニットへ移る。","f":"ノクタールの契約者たちは己の掌を裂き、刃に血を吸わせる。流した血が多いほど、刃は遠くまで届く。","b":"{味方全体} ♥−1|{敵前1体} ♥− 削れた合計×3、余りは次へ","h":"gm8qhl"},
"SA2-01": {"n":"突撃ラッパ","t":"味方の先頭ユニット2体の攻撃+1 +1C。","f":"暁城の城壁の上でラッパが鳴る。前列の騎士たちが陽を背に駆け出す。","b":"{味方前2体} ⚔+1 +1C","h":"j6lisq"},
"SA2-02": {"n":"忍耐の祈り","t":"味方の先頭ユニット2体に[加護 1]。","f":"夜明け前が最も暗い。天族はその闇の中で受けた刃を一つずつ祈りのように数える — 数えた分だけ夜が明けてくる。","b":"{味方前2体} [加護 1]","h":"ca3rze"},
"SA2-03": {"n":"沈黙の祈り","t":"相手の先頭ユニット2体の特殊能力をこのターン封じる。味方に[浄化]ユニットがいれば相手ユニット全体。","f":"天族の司祭たちが声を揃えて祈ると、戦場の喧騒が静まる。その沈黙の中では、どんな力も己の名を呼べない。","b":"{敵前2体} 能力封じ|[浄化]がいれば {敵全体}","h":"lznqdl"},
"SA2-04": {"n":"正義の一撃","t":"相手の先頭ユニットの体力−2。味方の先頭ユニットに[障壁]。","f":"剣が振り下ろされる瞬間、光が戻って振るう者を包む。正義は斬る者も守る。","b":"{敵前1体} ♥−2|{味方前1体} [障壁]","h":"7kkx4z"},
"SA2-07": {"n":"審判の天秤","t":"同じ特殊能力を持つ相手ユニットが2体以上いれば、それらの攻撃がこのターンそれぞれのレベル分下がる。","f":"ソランテの天秤は、群れて同じ力を振るう者たちを共に量る。天秤に載った者は、位が重いほど刃が軽くなる。","b":"{敵 同じ能力2体+} ⚔ −レベル","h":"dy74t"},
"SA3-01": {"n":"突風","t":"相手先頭ユニットの防御−1 −1C。味方ユニット2体の攻撃+1。","f":"前から吹きつける突風が敵の鎧の隙間をこじ開ける。同じ風が後列の仲間の背を押す。","b":"{敵前1体} ⛨−1 −1C|{味方2体} ⚔+1","h":"1onax43"},
"SA3-02": {"n":"混乱の風","t":"相手先頭ユニットの防御と残り体力を入れ替える(防御0だったユニットは体力0になり倒れる)。","f":"エルフの風は鎧を剥がさない。ただ身が鎧か、鎧が身かわからぬほど混ぜ合わせる。その先は矢が知っている。","b":"{敵前1体} ⛨ ↔ ♥","h":"1nm3yzd"},
"SA3-04": {"n":"弦引き","t":"味方先頭ユニット2体の攻撃+2 +1C、[遠隔]。","f":"弓士会の射手たちが一斉に弦を耳元まで引く。この距離なら刃は届かない。","b":"{味方前2体} ⚔+2 +1C|[遠隔]","h":"1lk717t"},
"SA3-05": {"n":"射返す風","t":"味方先頭ユニット2体の防御+2、体力+2、[防御無視](このターン — 反撃時も相手の防御を無視)。","f":"針の塔の射手は打たれても退かない。身を包む旋風が刃を流す間に、弦はもう刃の主の鎧の隙間を狙っている。","b":"{味方前2体} ⛨+2 ♥+2 [防御無視]","h":"15l24s1"},
"SA3-06": {"n":"弓士会の武器庫","t":"アイテムを装備していない味方ユニット全体が[弓]を持つ(この対戦中ずっと)。弓を得たユニットはこのターン攻撃+2、[遠隔]。","f":"嵐の塔弓士会の武器庫の扉が開く。剣を握っていた手にも、爪しかない獣にも、風をまとった弓が一張りずつ渡される。","b":"{アイテムなし味方} 🏹[弓] (対戦中)|⚔+2 [遠隔]","h":"lr6me5"},
"SA3-08": {"n":"大嵐","t":"相手ユニット全体の攻撃−1 −1C。相手先頭ユニットはこのターン攻撃も反撃もしない。","f":"嵐の塔弓士会が一斉に弦を放つ合図。矢より先に、立っていられないほどの風が戦場を覆う。","b":"{敵全体} ⚔−1 −1C|{敵前1体} 攻撃・反撃封じ","h":"qvpzs2"},
"SB1-01": {"n":"煙幕弾","t":"敵ユニット3体の攻撃−2。そのうち火傷のあるユニットはさらに攻撃−2。","f":"鼻を刺す硝煙が戦場を覆う。火が燃え移った者は、煙の中で目を開けられない。","b":"{敵3体} ⚔−2|火傷ならさらに⚔−2","h":"zz1t3w"},
"SB1-03": {"n":"炎の帳","t":"味方の先頭ユニット2体の体力+1、[炎の鎧 2]。","f":"塹壕の前に油を撒いて火を放つ。剣を手に越えてくる者は、火をまとって帰っていく。","b":"{味方前2体} ♥+1|[炎の鎧 2]","h":"2tjm2z"},
"SB1-05": {"n":"起爆","t":"敵の先頭ユニットに火傷2。その後、敵ユニットの火傷をすべて今すぐ爆発させる——火傷のあったユニットはさらにダメージ2。","f":"フォルタンの工兵は火種がひとりでに燃え上がるのを待たない。合図ひとつで、仕掛けた火が一斉に爆ぜる。","b":"{敵前1体} 火傷2|{敵の火傷} 即爆発 +2","h":"ogb6g9"},
"SB1-06": {"n":"防衛砲台","t":"敵ユニット2体の体力−3。","f":"城壁の裏に隠した大砲が、迫る敵の後列を狙う。前列は振り返って初めて知った。","b":"{敵2体} ♥−3","h":"3oidc"},
"SB1-08": {"n":"火薬庫爆破","t":"味方の火薬樽N個をすべて爆発させて破壊。爆発させた樽の数だけ、敵ユニットの体力−N²、[火傷 2]。味方ユニット全体の体力−N。","f":"ドルマクの火薬庫に火種がひとつ落ちれば、フォルタンのすべての火薬樽が同じ息で応える。","b":"{味方の樽N} 破壊|{敵N体} ♥−N² 火傷2|{味方全体} ♥−N","h":"r137yy"},
"SB1-09": {"n":"大砲撃","t":"敵ユニット全体の体力−3。[装填 2]","f":"砲台全体が息を合わせ、一度に撃ち込んだ。野の形はその日から変わった。","b":"{敵全体} ♥−3","h":"law91g"},
"SB2-01": {"n":"鉄甲突撃","t":"味方ユニット2体の攻撃+2、防御+1。","f":"鉄の鎧のドワーフたちが肩を並べて突進する。遅いが、一度走り出せば誰にも止められない。","b":"{味方2体} ⚔+2 ⛨+1","h":"1p54com"},
"SB2-02": {"n":"リベット射出","t":"相手の先頭ユニットの防御−2、体力−1。","f":"圧縮蒸気で熱したリベットを撃ち出す。刺さるのが鎧でも盾でも構わない。","b":"{敵前1体} ⛨−2 ♥−1","h":"8d5f8y"},
"SB2-03": {"n":"溶接修理","t":"味方の先頭ユニットの体力+2 +1C。","f":"戦場の只中でも火花を散らし、割れた鉄を繋ぐ。ドゥルクハイムの職人は戦場も工房と心得る。","b":"{味方前1体} ♥+2 +1C","h":"142q9gb"},
"SB2-06": {"n":"圧搾プレス","t":"相手の先頭ユニットの体力−1。味方ユニット3体の攻撃+1。","f":"工房の巨大なプレス機を戦場へ引き出した。鉄を延ばす力は、敵を延ばすのにも役立った。","b":"{敵前1体} ♥−1|{味方3体} ⚔+1","h":"1ojbgaa"},
"SB2-09": {"n":"大工房","t":"味方全体の防御+1、体力+1 +1C。味方全体に[呪い免疫]。","f":"ドゥルクハイムの全溶鉱炉に火が入った。地下都市全体が一つの工房となって戦いを支える。","b":"{味方全体} ⛨+1 ♥+1 +1C|{味方全体} [呪い免疫]","h":"1n4eff1"},
"SB3-01": {"n":"静電気","t":"敵ユニット3体の体力−1 −1C。","f":"こすった毛皮から散った小さな火花。ノームは偉大な実験はすべてここから始まったと教える。","b":"{敵3体} ♥−1 −1C","h":"1gjl2h5"},
"SB3-02": {"n":"避雷針","t":"相手の先頭ユニット2体の攻撃−1 −1C×2。","f":"空の雷を奪い、地へ流す。アストラクがヴォルタリウムを仇とする訳だ。","b":"{敵前2体} ⚔−1 −1C×2","h":"14gv97z"},
"SB3-03": {"n":"充電コイル","t":"味方の先頭ユニット2体の攻撃+1 +1C×2。","f":"銅線を何千回も巻いて雷を捕らえておく。巻くほど指先の唸りが大きくなる。","b":"{味方前2体} ⚔+1 +1C×2","h":"8rboxv"},
"SB3-04": {"n":"電撃の帳","t":"敵ユニット3体の体力−1 −1C×2。","f":"ヴォルタリウムの前に雷の帳を下ろした。越えようとした者は指先から痺れて足を止めた。","b":"{敵3体} ♥−1 −1C×2","h":"7xf69h"},
"SB3-05": {"n":"蓄電防壁","t":"味方の先頭ユニット2体の防御+1。相手の先頭ユニットの体力−2 −1C。","f":"蓄電器を並べて雷の壁を築いた。触れた刃はまず持ち主の手に噛みついた。","b":"{味方前2体} ⛨+1|{敵前1体} ♥−2 −1C","h":"1k6glkn"},
"SB3-06": {"n":"雷雲召喚","t":"相手ユニット全体の体力−1 −1C。","f":"雷鳴高原の雲を装置で引き寄せた。黒雲が頭上に届くと、ノームたちは傘を開いた。","b":"{敵全体} ♥−1 −1C","h":"1yxmj3w"},
"SB3-09": {"n":"霹靂の嵐","t":"相手ユニット全体の体力−1 −1C×2。","f":"高原の嵐を丸ごとヴォルタリウムの上へ運んだ。その日、空からは雨より雷が多く降った。","b":"{敵全体} ♥−1 −1C×2","h":"1pvuhdk"},
"SG1-01": {"n":"獲物追い","t":"相手ユニットを残り体力の低い順に先頭から並べ直す。","f":"オークの狩人は群れで一番弱い獣から追い出す。前へ押し出された者に、牙から逃げる場所はない。","b":"{敵} ♥の低い順に先頭から","h":"x41fjm"},
"SG1-02": {"n":"とどめ","t":"相手ユニット全体の体力−1。","f":"オークはよろめく敵に背を見せない。牙にかかって耐える者から順に息の根を止める。","b":"{敵全体} ♥−1","h":"196y8u"},
"SG1-03": {"n":"窮地の牙","t":"味方ユニットの攻撃の合計だけ、相手の先頭ユニットから攻撃→防御→体力の順に削る(攻撃・防御はこのターン)。削り切って倒すと、残りは次のユニットへ移る。","f":"追い詰められた群れが一斉に牙を立てる。前を塞ぐ者から爪・鎧・息の根の順に食いちぎられる。","b":"{敵の先頭から} ⚔ → ⛨ → ♥ 削る|量 = {味方} ⚔ 合計・余りは次へ","h":"t4cs3v"},
"SG1-04": {"n":"獲物の印","t":"相手の先頭ユニットの防御−2、体力−1。","f":"狩人が敵の額に土で線を引く。その線を見た群れは、その一体だけを追う。","b":"{敵前1体} ⛨−2 ♥−1","h":"g8e8ih"},
"SG1-08": {"n":"牙の反撃","t":"味方ユニット全体の体力+2、[致命]。","f":"追い詰められたオークは退かずに噛みつく。飛びかかった者は生きて帰っても、息はひと筋しか残らない。","b":"{味方全体} ♥+2 [致命]","h":"11z4wsz"},
"SG1-09": {"n":"体当たり","t":"相手ユニット全体の体力−(味方ユニット数×2)。その後、味方ユニットそれぞれの体力−(味方ユニット数)。","f":"群れがひと塊になって身を投げる。ぶつかった側も砕けるが、受けた側はもっと砕ける。","b":"{敵全体} ♥ −(味方数×2)|{味方全体} ♥ −(味方数)","h":"oa4zza"},
"SG2-01": {"n":"蔓締め","t":"防御が最も高い敵ユニット1体にダメージ(そのユニットの防御×2)。","f":"蔓は鎧の継ぎ目を探して食い込む。鎧が厚いほど深く刺さり、強く締め上げる。","b":"{敵防御最高1} ダメージ ⛨×2","h":"1qutwq4"},
"SG2-02": {"n":"新芽の鎧","t":"味方先頭ユニットの防御+1、[再生 2]。","f":"裂けた樹皮の隙間ごとに新芽が生え、傷を覆う。切り払っても次の瞬間にはまた生える。","b":"{味方前1体} ⛨+1 [再生 2]","h":"1l8cbeo"},
"SG2-03": {"n":"茨の垣根","t":"味方ユニット2体に[棘 2]。","f":"一夜のうちに陣の周りに茨が育つ。越えようとする者は棘を思い知る。","b":"{味方2体} [棘 2]","h":"1mf2m6l"},
"SG2-04": {"n":"トレントの行進","t":"味方ユニット3体の攻撃+1、体力+3。","f":"トレントたちが根を抜いて歩き始める。その歩みは遅いが、止めることもできない。","b":"{味方3体} ⚔+1 ♥+3","h":"oz6jhn"},
"SG2-05": {"n":"樹液寄せ","t":"体力が最も高い味方ユニット1体に、他の味方ユニットの体力を1だけ残してすべて集める(差し出したユニットごとに+1)。そのユニット1体はこのターン[守護]。","f":"トロールたちが古木の根元に掌を当てる。全身の樹液が根を伝って一本へ流れ込み、その古木だけが張り裂けんばかりに膨らむ。","b":"{味方} ♥ → 1|すべて {♥最高1} へ (+1ずつ) · 守護","h":"v5rmer"},
"SG2-07": {"n":"アザミの砦","t":"味方先頭ユニット2体の防御+1、[棘 2]。","f":"アザミが瞬く間に育ち、城壁となる。その内に立つトロールたちは、ようやく背を預ける場所を得る。","b":"{味方前2体} ⛨+1 [棘 2]","h":"16b6flv"},
"SG2-08": {"n":"古木落とし","t":"体力が最も高い味方ユニットの体力が半分になり(切り捨て)、減った分だけ防御1以上の敵ユニットにダメージ。","f":"古木が根ごと身を起こし、抱えた樹液の重みを乗せて叩きつける。大地が陥ち、古木は樹皮の半分を失う。","b":"{♥最高1} ♥ 半分|減った分 {防御ある敵全体} にダメージ","h":"17di8og"},
"SG2-09": {"n":"ヴェルダンの古木","t":"味方全体の防御+1、[棘 2]。","f":"竜の角から落ちた枝が一夜で古木に育つ。その棘の陰に盟約の戦士たちが立つ。","b":"{味方全体} ⛨+1 [棘 2]","h":"n1hfnc"},
"SG3-01": {"n":"幻惑の支配","t":"この魔法のすぐ後ろの自分のカードと名前の文字数(空白を除く)が同じ敵カードのうち、先頭の1枚を奪い自分の戦場の最後尾に置く。ユニットは対戦終了まで自分のユニットになり、魔法は自分の魔法として発動する。","f":"セレネアの巫女は名を歌う。同じ長さの名を持つ者はその歌を己の名と聞き、夢うつつに水中の陣へ歩み入る。","b":"{後ろと同字数の敵カード1枚} 奪う","h":"8k684g"},
"SG3-02": {"n":"水光の蜃気楼","t":"敵ユニットのうちランダムな2体の攻撃と体力を入れ替える。","f":"水の光が揺らめけば、目に映るものが裏返る。巨人は葦のようによろめき、臆病者は己の影に驚いて剣を振るう。誰がそうなるかは波だけが知る。","b":"{敵ランダム2体} ⚔ ↔ ♥","h":"1dsu3pi"},
"SG3-03": {"n":"水の帳","t":"味方先頭ユニット2体がこのターン受けるダメージ−1(激突・魔法・棘すべて。人魚のオーラ「海の守り」と同じ扱い)。味方先頭ユニットにこのターン[浄化]。","f":"巫女が水を持ち上げ、薄い帳を張る。剣は帳を抜けるうちに力を失う。","b":"{味方前2体} 被ダメージ−1|{味方前1体} [浄化]","h":"qml8w0"},
"SG3-09": {"n":"大海流","t":"敵ユニット全体のコインが裏になる(コイン確率−50%、すでに決まったコインはそのまま)。味方先頭ユニットにこのターン[治癒 1]。","f":"南の海の大海流が向きを変える。敵が頼んだ運もその流れと共に流れ去る。","b":"{敵全体} コイン裏|{味方前1体} [治癒 1]","h":"1n7dcvs"},
"SP-A1": {"n":"影なきアズラ","f":"沈黙の君主モルカスと向かい合い、代価を払ってなお借りを負わなかった唯一の存在。天秤に何を載せたのかは誰も知らない。その日から陽が昇ってもその足元に影はなく、ノクタールのすべての影が彼女の方へ傾く。","h":"1xgn3b9"},
"SP-A2": {"n":"ソランテの最初の騎士","f":"暁の母ソランテに初めて誓った存在。ソランテはその誓いを聞き、自ら彼を抱き上げた。聖光騎士団のすべての誓いは今も彼の言葉をなぞって唱えられる。彼が剣を掲げる場所に、夜は来られない。","h":"1okmck0"},
"SP-A3": {"n":"星を解くイサク","f":"星の文字を初めて読み解いた者。読み終えた夜、彼は星座をひとつ解いて編み直し、空はそれに従った。嵐の塔弓士会は、彼の遺した最初の一頁をまだ読み終えていない。","h":"xbf6zi"},
"SP-B1": {"n":"火を呑みし者","f":"眠れる巨人ドルマクの心火を丸ごと呑んだ存在。その一息が砲台ひとつの一斉射撃であり、火冠山脈は彼が息をする時だけ燃え上がる。フォルタンの砲手は彼の名を呼ばない——応えられては困るから。","h":"kn41n2"},
"SP-B2": {"n":"鉄の心臓を呑んだ者","f":"巨人ソルグリムの腱を溶かして鍛えた鉄の心臓を、己の胸に呑み込んだ者。その心臓が初めて脈打った日、ドゥルクハイムの全ゴーレムが共に目覚めた。彼の名がブロンだったと覚えているのは、今や彼が最初に作ったゴーレムだけだ。","h":"qvtsgi"},
"SP-B3": {"n":"七番目","f":"ヴォルタリウムは巨人ケラウンの神経に六つの機械を繋ぎ、六つとも焼き切れた。七番目は目を開いた。その中で考えるのがヴォルタリウムの設計か、眠る巨人の夢か — 造り手さえ今は彼を見上げ、答えを待つ。","h":"jladek"},
"SP-G1": {"n":"灰鬣のカルノ","f":"百度の決闘の末、大地の竜ゴルヴァスに認められた者。百一度目の相手こそその竜だったという話もある。今も強者を探して決闘を挑み、彼の通った草原には灰色の鬣のような煙が長く残る。","h":"w2ivlp"},
"SP-G2": {"n":"銀月のリシエル","f":"月の満ちゆく夜にだけ歩く森。燃えるエイレン大森林の炎を全身で受け止め、その灰の上に一夜で千年の森を建て直した。精霊か昇天者か、学者の間でも意見が割れる。","h":"14but7z"},
"SP-G3": {"n":"海を鎮める者","f":"水の竜マレンシアが覚える最も古い歌が体を得たもの。その歌が海底に眠る巨人タラクスを眠らせる。剣が水を斬れぬように、彼女も斬れない。近ごろその歌は少しずつ長くなっている。","h":"1cyfalk"},
"SR-A1": {"n":"ハルガンの両手剣","f":"審判者ハルガンの剣。ただ一度、神を罰する時に抜かれたという。判決の前に鎧は意味をなさない。","h":"xp1q65"},
"SR-A2": {"n":"セレンの弓","f":"門番セレンが世界の境の向こうを狙っていた弓。越えようとするものは、届く前に倒れる。","h":"m8vcbu"},
"SR-A3": {"n":"イヴェルの羽ペン","f":"記録者イヴェルの羽ペン。このペンで記されたことは、起きたことになる。","h":"c1i4qh"},
"SR-B1": {"n":"ドルマクの肋骨炉","f":"火冠山脈の下に横たわる巨人ドルマクの肋骨を削った炉。中で冷めぬ心火が燃え、すでに火のついたものを見るとさらに燃え上がる。","h":"1avidfj"},
"SR-B2": {"n":"ソルグリムの初の鎧","f":"眠る巨人ソルグリムの肋の節をそのまま剥がした鎧。打ち込んだ刃は、防がれた瞬間その重さのまま打った者へ返る。","h":"1gh9fpp"},
"SR-B3": {"n":"ケラウンの霹靂心臓","f":"雷に打たれても止まらなかった巨人ケラウンの心臓の欠片。魔法が起こるたび一度強く脈打ち、持つ者の腕に霹靂を宿す。","h":"dor3rf"},
"SR-G1": {"n":"ゴルヴァスの折れ牙","f":"大地の竜ゴルヴァスが初めての狩りで折った牙。持つ者は倒したものを呑むたび、竜のように大きくなる。","h":"ng31z6"},
"SR-G2": {"n":"ヴェルダンの初角","f":"森の竜ヴェルダンが初めて生え替わらせた角。角から伸びた根が、挑んだ者の息を吸って主の傷を埋める。","h":"1t8161"},
"SR-G3": {"n":"マレンシアの涙杯","f":"水の竜マレンシアが盟約の日に流した涙を受けた聖杯。戦いが始まると、満ち潮は最も深く斬られた者に先に届く。","h":"2escw"},
"TK-A1-1": {"n":"封蝋の使い魔","f":"命を受けて封蝋から起き上がった使い魔。","k":"封蝋の精","h":"hlt51w"},
"TK-A2-1": {"n":"光の騎士","f":"一つの誓いが光で形作られた騎士。誓いが折れぬゆえ、その剣も折れない。","k":"誓魂","h":"19rt2jo"},
"TK-B2-1": {"n":"番兵ゴーレム","f":"工房が非常時に起動する小さな番兵ゴーレム。","k":"ゴーレム","h":"r9zczc"},
"TK-G1-1": {"n":"影ハイエナ","f":"影から飛び出して一度噛み、笑い声だけ残して消えるハイエナ。","k":"ハイエナ","h":"5hiknq"},
"TK-G1-2": {"n":"頭目ハイエナ","f":"呼び声に応えた群れの頭目。笑い声が一番低い。","k":"ハイエナ","h":"1ssr25s"},
"TK-G2-1": {"n":"蔓の防壁","f":"一ターンの間だけ伸びて枯れる蔓の壁。","k":"トレント","h":"68dfdz"},
"TK-G3-1": {"n":"水の精霊","f":"泉から立ち上がった小さな精霊。","k":"ウンディーネ","h":"1alq71y"},
"TK-U-BOMB": {"n":"火のついた火薬樽","f":"導火線が燃えていく。次の戦闘の最初の魔法が過ぎれば爆ぜる。","k":"爆弾","h":"1salvm9"},
"TK-U-ROOT": {"n":"根","f":"切り倒された古木の切り株から、一夜でまた伸びた根。倒れた者を抱きしめて離さない。","k":"トレント","h":"9k0vpf"},
"TK-U-SAPLING": {"n":"苗木","f":"戦いが終わった場所に植えた苗木。","k":"トレント","h":"ja6kds"},
"TK-U-SCRAP": {"n":"屑鉄ゴーレム","f":"倒れた仲間の部品で組んだゴーレム。","k":"ゴーレム","h":"104wnt4"},
"TK-U-TREE": {"n":"若い古木","f":"一ターンを耐えた苗木が育った古木。","k":"トレント","h":"4pj5k0"},
"TK-U-WOLF": {"n":"灰色の塵獣","f":"大族長の咆哮で土埃から起きた獣。次の戦いが終われば、また塵に散る。","k":"塵の獣","h":"awcmx"},
"TS-A3-1": {"n":"流星の欠片","t":"相手ランダムユニット1体にダメージ1。","b":"{敵ランダム} ダメージ1","h":"82a3qh"},
"TS-A3-2": {"n":"つむじ風","t":"相手ランダムユニット1体にダメージ2。","b":"{敵ランダム} ダメージ2","h":"a2bjhf"},
"TS-A3-3": {"n":"火種","t":"相手先頭ユニットにダメージ1。","b":"{敵前1体} ダメージ1","h":"8g635z"},
"TS-A3-4": {"n":"双子の木霊","t":"相手先頭2体にダメージ1。","b":"{敵前2体} ダメージ1","h":"85g62x"},
"UN-A1": {"n":"血の誓約者","f":"ノクタール深淵契約団で己の血で誓約書を書いた吸血君主。その剣に斬られた者は契約の代価を共に払う。","k":"吸血君主","h":"wutze8"},
"UN-A1-7": {"n":"モルカスの魂狩り","f":"モルカスに魂を捧げて体を失った深淵の君主。空の黒曜の鎧で他者の魂を刈るたび契約書が一枚手に残るが、己の魂はまだ返ってこない。","k":"深淵君主","h":"mvj33j"},
"UN-A2": {"n":"エラドの翼盾","f":"暁城エラドの聖光騎士。仲間の前に翼を広げ、代わりに受ける。","k":"翼の巨神","h":"i7ib0t"},
"UN-A2-7": {"n":"ソランテの暁司祭","f":"ソランテの暁の光を金の輪に掲げる太陽の使徒。彼が歩み来れば陽が昇り、倒れた騎士が再び立つ。","k":"太陽の使徒","h":"qg8by5"},
"UN-A3": {"n":"針の塔の星守","f":"ベルミルの針の塔に巻きつき、星と風を共に読む星鱗の竜。敵の呪文が風に乗る前に、もう目をそちらへ向けている。","k":"星鱗竜","h":"7wdf52"},
"UN-A3-7": {"n":"ベルミルの呪文狩り","f":"他者の呪文だけを射落とす星硝子の巨神。呪文の光を真っ先に見つけ、矢じりに貫かれた呪文はその三日月の弓へ吸い込まれる。","k":"星硝子の巨神","h":"1tr35y6"},
"UN-B1": {"n":"フォルタン砲兵長","f":"フォルタン火薬砲兵団を率いる角ある炎魔。倒れる時も導火線に火をつけておく。","k":"炎魔","h":"d5e58f"},
"UN-B1-7": {"n":"タラクスの火種砲手","f":"タラクスの脈動から汲んだ火種を砲弾に植える溶岩竜。撃たれた場所は翌日も燃えている。","k":"溶岩竜","h":"1xs40rd"},
"UN-B2": {"n":"ブロンの最初のゴーレム","f":"鉄の心臓を呑んだ者が最初に作ったゴーレム。主がブロンと呼ばれていた頃を覚える最後の存在。倒れた仲間の部品を拾い集め、新たなゴーレムを組む。","k":"ゴーレム","h":"c6gzjv"},
"UN-B2-7": {"n":"ドゥルクハイム鎖ゴーレム","f":"ドゥルクハイムの城門を守る二体のゴーレムを、鋼の鎖一本で繋いだ。一体が打たれれば二体で耐える。","k":"ゴーレム","h":"16cgxr3"},
"UN-B3": {"n":"ズラクの瓶守","f":"雷の大精霊ズラクを瓶に封じた、ヴォルタリウムの銅仮面の雷神。魔法がかすめるたび、空の瓶に雷が再び溜まる。","k":"雷神","h":"qyolsh"},
"UN-B3-7": {"n":"ケラウン磁場塔","f":"ケラウンの雷を巻きつけた歩く塔。近づく者の運までねじ曲げる。","k":"雷電塔","h":"1yu40j3"},
"UN-G1": {"n":"岩牙の大族長","f":"ガルウン岩牙族の頭目。彼が敵を倒すと、群れが吠えながら駆けつける。","k":"牙の巨人","h":"1ailes7"},
"UN-G1-7": {"n":"ガルウン略奪王","f":"倒した敵の武器をその場で拾い上げる六腕の巨人王。ガルウンではそれを礼儀と呼ぶ。","k":"六腕の巨人","h":"ekaadj"},
"UN-G2": {"n":"初古木の棘守り","f":"シルヴァニエルの始まりの古木の周りに茨を育てる老トレント。切り倒しても根が残る。","k":"トレント","h":"1keyu36"},
"UN-G2-7": {"n":"ヴェルダンの種守り","f":"枝ごとに種袋を下げて歩く老トレント。戦いが終わった場所ごとに森が育つ。","k":"トレント","h":"1ookx8c"},
"UN-G3": {"n":"泉の歌い手","f":"セレネア泉の巫女団の歌い手。その歌を聞いた死者は海へ還り、また打ち寄せてくる。","k":"珊瑚の女神","h":"q6eslk"},
"UN-G3-7": {"n":"マレンシアのセイレーン","f":"マレンシアの深い水から歌と共に上ってきたセイレーン。その歌を最後まで聞いた敵は剣を逆手に握る。","k":"セイレーン","h":"8d7oi9"},
"UP-A1-09": {"n":"モルクの蜘蛛女王","f":"峡谷の壁一面を覆うほど糸を張ったら、子が生まれた。今やモルク峡谷に落ちるものは、まず彼女の取り分から差し引かれる。","k":"影蜘蛛","h":"og5fno"},
"UP-A1-11": {"n":"契約団の鼠先鋒","f":"戦士三人のうち生きて戻ったひとりが、残る二人の契約まで背負った。","k":"鼠","h":"hynxsu"},
"UP-A1-15": {"n":"血を啜る魔剣","f":"血を啜る剣が三人の主の血を飲み干し、魔剣となった。もはや振るう手を待たない。","k":"呪いの剣","h":"1leesj1"},
"UP-A1-18": {"n":"影の殺戮者","f":"影の中で待ちはしない。影を引きずって歩く。","k":"影の獣","h":"jwd1jy"},
"UP-A1-23": {"n":"大鎌の死神","f":"刈り取った契約書が膝まで積もった時、鎌を替えた。今は名をひとつずつではなく、一列ずつ呼ぶ。","k":"死神","h":"131wxen"},
"UP-A2-11": {"n":"槍角ユニコーン","f":"角が槍ほどに伸びた。闇はその角先の暁の光が届く前に裂ける。","k":"ユニコーン","h":"z1vpbh"},
"UP-A2-15": {"n":"ソランテの誓約騎士","f":"誓いを三度守った者だけが誓約の甲冑をまとう。","k":"聖像","h":"1pguka6"},
"UP-A2-17": {"n":"黄金のスフィンクス","f":"問いを投げていたスフィンクスが、ソランテの光を長く浴びて金色になった。今は問わずとも、偽りはその前で影を失う。","k":"スフィンクス","h":"1cf5u3u"},
"UP-A2-22": {"n":"ソランテの大聖鐘","f":"毎朝鳴っていた鐘が大聖堂の頂へ移された。今やその音は黄昏の障壁まで届く。","k":"聖鐘の精","h":"x6h1bp"},
"UP-A2-24": {"n":"光の大鏡","f":"回廊の鏡が三枚に重なって育った。裏の銀には、黄昏の障壁から運んだ石粉が混じっている。","k":"鏡の精","h":"1a105v9"},
"UP-A3-10": {"n":"速射ハーピー","f":"羽根を惜しむことはついに覚えなかった。代わりに、抜けるそばから生えるようになった。","k":"ハーピー","h":"dxkn79"},
"UP-A3-11": {"n":"疾風グリフィン","f":"雛の頃、便りより先に着いた癖がそのまま育った。今は風より先に着き、それ自体が便りとなる。","k":"グリフィン","h":"19983x5"},
"UP-A3-18": {"n":"双子座の弓士長","f":"二つの星は弦の音をひとつに合わせる術を覚えた。今や双子座の矢はひとつとして飛び、二つとして刺さる。","k":"星座","h":"u660e3"},
"UP-A3-23": {"n":"星狐の巡察隊長","f":"高原の道を歩き尽くした星狐は、敵がどの道から来るかを先に嗅ぎつける。尾の星明かりもそれだけ長くなった。","k":"星狐","h":"17d8k7l"},
"UP-A3-24": {"n":"雷天狗の頭","f":"雷を矢に乗せる術はとうに覚えた。それを望む場所にだけ落とせる天狗は、針の塔に彼ひとりだ。","k":"天狗","h":"1y4zj2m"},
"UP-B1-12": {"n":"爆薬工兵長","f":"火鼠の群れの中で火薬庫の下を最も深く掘った頭目。フォルタンの工兵はその穴に沿って爆薬を埋め、ついに工兵長の名を与えた。","k":"火鼠","h":"16ib0od"},
"UP-B1-17": {"n":"巨砲亀","f":"砲台亀がさらに百年を経ると、甲羅の火口が三つに割れた。一息吐けば音は三つ、だが地が沈むのは一度だけ。","k":"溶岩亀","h":"1yqm75z"},
"UP-B1-18": {"n":"火蟻の鉄壁隊","f":"火薬庫を守っていた火蟻の群れが殻を合わせ、ひとつの壁となった。打たれるほど殻は熱を帯び、硬くなる。","k":"火蟻","h":"rfohvm"},
"UP-B1-24": {"n":"迫撃の名手","f":"フォルタンの迫撃手たちは、彼の砲弾の軌跡を見て角度を直す。","k":"ウルヴァリン","h":"4xq7hs"},
"UP-B2-12": {"n":"鍛冶の名匠","f":"見習いの槌三本を溶かし、職人の槌一本を鍛えた。","k":"鉄の猿","h":"9zn1x8"},
"UP-B2-17": {"n":"鉄角ヤギの王","f":"鉄角ヤギが角を幾度も生え替わらせ、群れの王となった。群れは彼の背の後ろにだけ並び、その背が城壁だ。","k":"鉄角ヤギ","h":"1qa9v1z"},
"UP-B2-18": {"n":"蒸気牡牛の頭領","f":"蒸気鼻息の牡牛が腹のボイラーを三つに増やし、群れの頭となった。一度地を踏み鳴らせば坑道の果てまで響く。","k":"青銅の牡牛","h":"n7u0co"},
"UP-B2-22": {"n":"プルガサリの王","f":"鉄喰いプルガサリが工房の屑鉄の山一つを丸呑みし、また育った。今では群れが後を追い、残りくずを拾う。","k":"プルガサリ","h":"vzyct2"},
"UP-B2-24": {"n":"ガーゴイル門番","f":"鉄骨ガーゴイルがドゥルクハイム最下層の坑道の門の上に居座った。その先に何があるかは語らない。","k":"鋼のガーゴイル","h":"93qw6e"},
"UP-B3-12": {"n":"放電妖精の女王","f":"三度弾けても消えなかった放電妖精が女王になった。四度目は弾けず、今は弾ける時を自ら選ぶ。","k":"スパーク妖精","h":"13pxikp"},
"UP-B3-18": {"n":"メガネザル主任技師","f":"三人の技師が争った設計を一晩でまとめてしまった。","k":"メガネザル","h":"q9f7e1"},
"UP-B3-22": {"n":"電撃守護巨像","f":"守護機三体のコイルを一つの体に巻いた。近づけば雷が先に打つ。","k":"雷電機関","h":"73x9hw"},
"UP-B3-23": {"n":"瓶詰め老教授の脳","f":"瓶詰め教授の脳が、他の教授二人の瓶と銅線で繋がった。三人が争った学説は、今や一つの瓶の中で果てしなく争う。","k":"瓶詰めの脳","h":"1deyw8y"},
"UP-G1-11": {"n":"黒曜の槍術師","f":"黒曜石の穂先を三度付け替えて、ようやく槍が手に馴染んだ。","k":"マングース","h":"ugydye"},
"UP-G1-18": {"n":"オーガの大呪術師","f":"ついにグロムの最初の音節を聞き終えたオーガ。以来、彼が太鼓を打てば、大地が残りを代わりに答える。","k":"オーガ","h":"dzoeh"},
"UP-G1-24": {"n":"ハイエナの大群れ長","f":"群れ長を三頭破り、草原のハイエナをひとつにまとめた。彼が笑えば草原が静まる。","k":"ハイエナ","h":"1ucq22h"},
"UP-G2-17": {"n":"ヒキガエル大呪術師","f":"冬眠を三度飛ばして呪術を極めた。苔が彼の言葉に従う。","k":"苔ヒキガエル","h":"obr1rh"},
"UP-G2-22": {"n":"マンドレイク門番","f":"土から自ら歩み出て、茨の森の門前に立った。今や悲鳴一つで門が閉じる。","k":"マンドレイク","h":"183ceud"},
"UP-G2-23": {"n":"ドリエンの大使徒","f":"ドリエンの言葉を三方へ運んでいた使徒たちが、一つの声となった。","k":"ドライアド","h":"1yar7ga"},
"UP-G3-11": {"n":"潮予言のタコ","f":"潮を読んでいたタコが、今は潮がいつ返るかを決める。八本の腕のうち七本をその仕事に使う。","k":"タコ","h":"txyjed"},
"UP-G3-12": {"n":"珊瑚甲羅の大亀","f":"背の珊瑚が三重に育ち、小さな岩島のようになった。珊瑚が育つほど、彼も遅く硬くなる。","k":"ウミガメ","h":"c8m2j"},
"UP-G3-17": {"n":"潟湖の大癒しジュゴン","f":"今では一息吐けば潟湖の水が温まる。傷ついた者三人を一度に背に乗せる。","k":"ジュゴン","h":"nrh5y3"},
"UP-G3-18": {"n":"水柱の珊瑚調律師","f":"珊瑚の枝が三つに分かれた。今は水柱三本の高さを揃え、一つの城壁のように立てる。","k":"珊瑚の精霊","h":"1wzca72"},
"UP-G3-24": {"n":"黒鬣のケルピー","f":"数えきれぬ渦を回した末、たてがみが深海のように黒くなった。今は潮がその蹄を追って回る。","k":"ケルピー","h":"147tq0i"},
"UP-PN-B3-C2": {"n":"手懐けた蓄電器","f":"暴走していた蓄電器に手綱をつけた。今は必要な分だけ爆ぜる。","k":"蓄電器","h":"mtl62n"},
"US-A1-1": {"n":"沈黙の天秤","t":"[生贄 4] 相手ユニットのうち攻撃が最も高いユニット2体を破壊する。","f":"沈黙の君主モルカスの天秤。片側に血を載せれば、もう片側から命がふたつ降りていく。","b":"{生贄} ライフ 4|{敵攻撃最高2体} 破壊","h":"olthjm"},
"US-A1-2": {"n":"影の契約","t":"[生贄 1] 相手ユニットのうち攻撃が最も高いユニット1体の体力−3。味方ユニット3体の攻撃+3、[致命]、[連鎖]。","f":"影なきアズラが初めて結んだという契約の写し。原本に何を賭けたのかは書かれていない。","b":"{敵攻撃最高1体} ♥−3 · 生贄1|{味方ユニット3体} ⚔+3 [致命] [連鎖]","h":"cwwoo2"},
"US-A2-1": {"n":"聖光の剣","t":"味方全体の攻撃+2、[防御無視]。","f":"暁の母ソランテが、盾を持つ手にも剣を握らせた日。光で鍛えた刃は鎧を見ない。","b":"{味方全体} ⚔+2 [防御無視]","h":"1rv2eq6"},
"US-A2-2": {"n":"太陽の審判","t":"相手ユニットのうち攻撃が最も高い2体の体力−4。味方の先頭ユニットに[障壁]。","f":"陽が最も高く昇った瞬間にだけ下される判決。刃を最も高く掲げた者から光に焼かれる。","b":"{敵 攻撃上位2体} ♥−4|{味方前1体} [障壁]","h":"1qv5b0h"},
"US-A3-1": {"n":"朔の契約書","t":"相手の手札のユニット全体の攻撃−1、体力−1(このゲーム中ずっと)。体力が0になると焼却される。呪い免疫の能力値は削られない。カードを1枚引く(ライフ消費なし)。","f":"朔の夜にノクタールで結ぶ契約書には、相手の名も共に記される。署名した者は一枚多く握り、記された者の札は手の中で萎れていく。","b":"{敵手札} ユニット全体 ⚔−1 ♥−1|カードを1枚引く","h":"7en7et"},
"US-A3-2": {"n":"ベルミルの目","t":"相手ユニット全体の攻撃−2、体力−2。相手先頭ユニット2体はこのターン攻撃も反撃もしない。","f":"千の目が嵌まったローブの神ベルミルが戦場を一度見下ろす。刃を握る手がその眼差しに止まる。","b":"{敵全体} ⚔−2 ♥−2|{敵前2体} 攻撃・反撃封じ","h":"1xetdal"},
"US-B1-1": {"n":"誘爆","t":"敵の先頭ユニットの体力−4。そのユニットが倒れたら、敵ユニット全体の体力−2。","f":"火薬運びが倒れれば荷も共に爆ぜる。フォルタン砲兵団はそれを戦術と呼ぶ。","b":"{敵前1体} ♥−4|{敵全体} 倒したら♥−2","h":"125osqb"},
"US-B1-2": {"n":"ドルマク砲撃","t":"敵ユニット全体の体力−2を二度。[装填 1]","f":"火冠山脈の下、巨人ドルマクの心火で焼いた砲弾。一度撃てば二度爆ぜる。","b":"{敵全体} ♥−2 ×2回","h":"1mwvt86"},
"US-B2-1": {"n":"鉄骨ハンマー","t":"味方全体の防御+1。その後、味方ユニットの防御の合計分、相手の先頭ユニットの体力を削る。倒して余った分は次のユニットへ。","f":"ゴーレムたちが一列に並び、一本の槌となる。ソルグリムの腕から掘った鉄で作った。","b":"{味方全体} ⛨+1|{敵先頭から} ♥− 味方⛨の合計 (余りは次へ)","h":"1dj8iw1"},
"US-B2-2": {"n":"鋼の行軍","t":"味方全体の攻撃+(味方ユニット数)。","f":"ドゥルクハイムのゴーレムが足並みを揃えると鉄骨山脈が鳴る。一体増えるごとに、全ての槌がその分重くなる。","b":"{味方全体} ⚔ + 味方ユニット数","h":"8gy1se"},
"US-B3-1": {"n":"雷の暴走","t":"相手のランダムなユニットに体力−1を6回。","f":"ヴォルタリウムの瓶が一度に割れた日。雷の行き先は雷も知らない。","b":"{敵ランダム} ♥−1 ×6回","h":"3tncib"},
"US-B3-2": {"n":"ケラウンの神経","t":"相手の待機列の先頭から順に体力−4 → −3 → −3 → −2。","f":"雷鳴高原の下に眠る巨人ケラウンの神経に触れた。雷が地上へ列をなして跳ね上がる。","b":"{敵先頭から} 順に ♥−4→−3→−3→−2","h":"1ep2wq1"},
"US-G1-1": {"n":"決闘申し込み","t":"味方の先頭ユニットの攻撃+4。そのユニットが攻撃の最も高い相手ユニット1体を先に打つ(物理ダメージ)。相手が生き残れば打ち返す。","f":"ガルウンのオークは最も強い者に先に刃を投げる。灰鬣のカルノが百度の決闘で残した掟だ。","b":"{味方前1体} ⚔+4|{敵 攻撃最高1体} 先制の決闘","h":"1yrhckj"},
"US-G1-2": {"n":"大地の激怒","t":"味方全体の攻撃+2。相手ユニット全体の体力−(味方ユニット数)。","f":"群れが一斉に足を踏み鳴らすと、大地の竜ゴルヴァスが寝ぼけて身じろぐ。","b":"{味方全体} ⚔+2|{敵全体} ♥− 味方ユニット数","h":"eg8zo"},
"US-G2-1": {"n":"再生の森","t":"味方ユニット1体の体力+3、[棘 2]。","f":"森の大精霊ドリエンが通った跡。切られた枝がその場でまたつながり、つながった所ごとに棘が生える。","b":"{味方1体} ♥+3 [棘 2]","h":"14isq47"},
"US-G2-2": {"n":"古木の怒り","t":"味方ユニットそれぞれの攻撃+(自身の残り体力の半分、切り上げ)。","f":"森の竜ヴェルダンが怒れば、千年耐えた古木が根ごと歩み出る。耐えてきた歳月がそのまま重みになる。","b":"{味方全体} ⚔ + 自身の♥の半分","h":"pb2id6"},
"US-G3-1": {"n":"ネリアの歌","t":"敵ユニット全体の[障壁]・[棘]・[呪い免疫]・[守護]が消え、コインが裏になる(すでに決まったコインはそのまま)。敵ユニット全体の体力−1。味方先頭ユニットにこのターン[浄化]。","f":"水の大精霊ネリアの歌。器によって姿を変える水のように、聞く者のあらゆる飾りを洗い流す。","b":"{敵全体} 能力解除・コイン裏|{敵全体} ♥−1|{味方前1体} [浄化]","h":"1xdt4zd"},
"US-G3-2": {"n":"潮の帰還","t":"敵ユニット全体の体力−2。味方全体の体力+1。味方先頭ユニットにこのターン[治癒 1]。","f":"タラクスの鼓動に合わせて退いた海が戻ってくる。敵は流され、味方は洗われる。","b":"{敵全体} ♥−2|{味方全体} ♥+1|{味方前1体} [治癒 1]","h":"3o2wki"}
};
